package com.timemeasurer.app.core.common.time

import kotlin.time.TimeSource

fun interface MonotonicClock {
    fun nowMs(): Long
}

object MonotonicClockImpl : MonotonicClock {
    private val startMark = TimeSource.Monotonic.markNow()

    override fun nowMs(): Long = startMark.elapsedNow().inWholeMilliseconds
}
