package com.timemeasurer.app.navigation

import androidx.compose.ui.graphics.vector.ImageVector
import com.timemeasurer.app.core.navigation.TopLevelDestination
import com.timemeasurer.app.core.resources.Res
import com.timemeasurer.app.core.resources.settings
import com.timemeasurer.app.core.resources.stopwatches
import com.timemeasurer.app.core.resources.timers
import com.timemeasurer.app.core.ui.icon.MainIconSet
import org.jetbrains.compose.resources.StringResource

val TopLevelDestination.selectedIcon: ImageVector
    get() = when (this) {
        TopLevelDestination.TIMERS -> MainIconSet.timerFilled.icon
        TopLevelDestination.STOPWATCHES -> MainIconSet.stopwatchFilled.icon
        TopLevelDestination.SETTINGS -> MainIconSet.settingsFilled.icon
    }

val TopLevelDestination.unselectedIcon: ImageVector
    get() = when (this) {
        TopLevelDestination.TIMERS -> MainIconSet.timer.icon
        TopLevelDestination.STOPWATCHES -> MainIconSet.stopwatch.icon
        TopLevelDestination.SETTINGS -> MainIconSet.settings.icon
    }

val TopLevelDestination.iconText: StringResource
    get() = when (this) {
        TopLevelDestination.TIMERS -> Res.string.timers
        TopLevelDestination.STOPWATCHES -> Res.string.stopwatches
        TopLevelDestination.SETTINGS -> Res.string.settings
    }
