package com.timemeasurer.app.core.common.di

import org.kodein.di.DirectDI
import org.kodein.di.instance

object Inject {

    private var diDirect: DirectDI? = null

    val di: DirectDI get() = requireNotNull(diDirect)

    fun createDependencies(tree: DirectDI) {
        diDirect = tree
    }

    inline fun <reified T> instance(tag: Any? = null): T {
        return di.instance(tag = tag)
    }
}