package com.timemeasurer.app.feature.timer_settings.widgets

import androidx.compose.foundation.layout.padding
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import com.timemeasurer.app.core.model.timer.TimerSettingsEvents
import com.timemeasurer.app.core.model.timer.TimerSettingsModel
import com.timemeasurer.app.core.resources.Res
import com.timemeasurer.app.core.resources.error_loading_timer_settings
import com.timemeasurer.app.core.resources.no_timer_found
import com.timemeasurer.app.core.ui.viewmodels.UiState
import com.timemeasurer.app.core.ui.widgets.CircularContent
import com.timemeasurer.app.core.ui.widgets.TimerSettingsForm
import org.jetbrains.compose.resources.stringResource


@Composable
internal fun TimerSettingsContent(
    state: UiState<TimerSettingsModel>,
    onEvent: (TimerSettingsEvents) -> Unit,
    modifier: Modifier = Modifier,
) {
    when (val currentState = state) {
        UiState.Loading -> CircularContent()
        UiState.Empty -> {
            Text(
                text = stringResource(Res.string.no_timer_found),
                modifier = modifier.padding(vertical = 16.dp),
            )
        }
        is UiState.Error -> {
            Text(
                text = stringResource(Res.string.error_loading_timer_settings),
                modifier = modifier.padding(vertical = 16.dp),
            )
        }
        is UiState.Success -> {
            TimerSettingsForm(
                settings = currentState.item,
                onSettingsChange = { newSettings ->
                    onEvent(TimerSettingsEvents.UpdateSessionDuration(newSettings.sessionDuration))
                    onEvent(TimerSettingsEvents.UpdateShortBreakDuration(newSettings.shortBreakDuration))
                    onEvent(TimerSettingsEvents.UpdateLongBreakDuration(newSettings.longBreakDuration))
                    onEvent(TimerSettingsEvents.UpdateSessionDurationUnit(newSettings.sessionDurationUnit))
                    onEvent(TimerSettingsEvents.UpdateShortBreakDurationUnit(newSettings.shortBreakDurationUnit))
                    onEvent(TimerSettingsEvents.UpdateLongBreakDurationUnit(newSettings.longBreakDurationUnit))
                    onEvent(TimerSettingsEvents.UpdateLongBreakAfterSession(newSettings.longBreakAfterSession))
                    onEvent(TimerSettingsEvents.UpdateIsTimerStartAuto(newSettings.isTimerStartAuto))
                    onEvent(TimerSettingsEvents.UpdateIsSessionStartAuto(newSettings.isSessionStartAuto))
                    onEvent(TimerSettingsEvents.UpdateIsBreakStartAuto(newSettings.isBreakStartAuto))
                    onEvent(TimerSettingsEvents.UpdateIsLongBreakEnabled(newSettings.isLongBreakEnabled))
                    onEvent(TimerSettingsEvents.UpdateIsShortBreakEnabled(newSettings.isShortBreakEnabled))
                    onEvent(TimerSettingsEvents.UpdateIsCountdownSoundEnabled(newSettings.isCountdownSoundEnabled))
                    onEvent(TimerSettingsEvents.UpdateCountdownSoundId(newSettings.countdownSoundId))
                    onEvent(TimerSettingsEvents.UpdateIsSessionEndSoundEnabled(newSettings.isSessionEndSoundEnabled))
                    onEvent(TimerSettingsEvents.UpdateSessionEndSoundId(newSettings.sessionEndSoundId))
                    onEvent(TimerSettingsEvents.UpdateIsRestEndSoundEnabled(newSettings.isRestEndSoundEnabled))
                    onEvent(TimerSettingsEvents.UpdateRestEndSoundId(newSettings.restEndSoundId))
                    onEvent(TimerSettingsEvents.UpdateProgressType(newSettings.progressType))
                },
                onPreviewSound = { soundId -> onEvent(TimerSettingsEvents.PreviewSound(soundId)) },
                onStopPreview = { onEvent(TimerSettingsEvents.StopPreviewSound) },
                onValidateSessionDuration = { onEvent(TimerSettingsEvents.ValidateSessionDuration) },
                onValidateShortBreakDuration = { onEvent(TimerSettingsEvents.ValidateShortBreakDuration) },
                onValidateLongBreakDuration = { onEvent(TimerSettingsEvents.ValidateLongBreakDuration) },
                onValidateLongBreakAfter = { onEvent(TimerSettingsEvents.ValidateLongBreakAfterSession) },
                modifier = modifier,
            )
        }
    }
}
