package com.timemeasurer.app.feature.stopwatches_statistics.models

import com.timemeasurer.app.core.model.stopwatch.StopwatchGraphType
import com.timemeasurer.app.core.model.stopwatch.StopwatchStatisticsModel
import com.timemeasurer.app.widget.graph.models.GraphModel
import com.timemeasurer.app.widget.graph.models.GraphType
import com.timemeasurer.app.widget.graph.models.Point

data class LapItem(
    val lapNumber: Int,
    val durationMillis: Long,
    val duration: String,
    val totalTimeFromStart: String,
)

data class StopwatchStatisticsItem(
    val stopwatchId: Long,
    val stopwatchName: String,
    val totalTime: String,
    val lapCount: String,
    val maxLapNumber: Int,
    val maxLapTime: String,
    val minLapNumber: Int,
    val minLapTime: String,
    val avgTime: String,
    val laps: List<LapItem>,
    val graphModels: List<GraphModel>,
    val graphType: StopwatchGraphType,
)

data class StopwatchesStatisticsUiModel(
    val items: List<StopwatchStatisticsItem>
)

val StopwatchGraphType.toGraphType: GraphType
    get() = when (this) {
        StopwatchGraphType.LINE -> GraphType.Line
        StopwatchGraphType.BAR -> GraphType.Bar
    }

val GraphType.toStopwatchGraphType: StopwatchGraphType
    get() = when (this) {
        GraphType.Line -> StopwatchGraphType.LINE
        GraphType.Bar -> StopwatchGraphType.BAR
    }

val StopwatchStatisticsModel.toStatisticsItem: StopwatchStatisticsItem
    get() = StopwatchStatisticsItem(
        stopwatchId = stopwatchId,
        stopwatchName = stopwatchName,
        totalTime = totalTime,
        lapCount = lapCount,
        maxLapNumber = maxLapNumber,
        maxLapTime = maxLapTime,
        minLapNumber = minLapNumber,
        minLapTime = minLapTime,
        avgTime = avgTime,
        laps = laps.map {
            LapItem(
                lapNumber = it.lapNumber,
                durationMillis = it.time,
                duration = it.time.toHoursMinutesSecondsMillis(),
                totalTimeFromStart = it.totalTimeFromStart.toHoursMinutesSecondsMillis(),
            )
        },
        graphModels = laps.mapIndexed { index, lap ->
            GraphModel(
                point = Point(
                    x = (index + 1).toFloat(),
                    y = lap.time.toFloat()
                )
            )
        },
        graphType = graphType,
    )

private fun Long.toHoursMinutesSecondsMillis(): String {
    val hours = this / 3_600_000
    val minutes = (this % 3_600_000) / 60_000
    val seconds = (this % 60_000) / 1_000
    val millis = this % 1_000
    val h = hours.toString().padStart(2, '0')
    val m = minutes.toString().padStart(2, '0')
    val s = seconds.toString().padStart(2, '0')
    val ms = millis.toString().padStart(3, '0')
    return "$h:$m:$s.$ms"
}
