package com.timemeasurer.app.core.ui.icon

object AppIconRegistry {
    val sets: List<IconSet> = listOf(
        MainIconSet.set,
        WorkIconSet.set,
        SportIconSet.set,
        RestIconSet.set,
        HobbyIconSet.set,
        EntertainmentIconSet.set,
        CommonIconSet.set,
        PlaybackIconSet.set,
        ChartIconSet.set,
    )

    val allIcons: List<IconModel> = sets.flatMap { it.icons }

    val defaultTimerIcon: IconModel = MainIconSet.timer
    val defaultStopwatchIcon: IconModel = MainIconSet.stopwatch

    fun findById(id: String): IconModel? = allIcons.find { it.id == id }
}
