package com.timemeasurer.app

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.timemeasurer.app.core.common.di.Inject
import com.timemeasurer.app.core.data.repositories.theme.ThemeRepository
import com.timemeasurer.app.core.domain.settings.KeepScreenOnSettingUseCase
import com.timemeasurer.app.core.model.ThemeData
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.combine
import kotlinx.coroutines.flow.stateIn

class AppViewModel(
    private val themeRepository: ThemeRepository = Inject.instance(),
    private val keepScreenOnSettingUseCase: KeepScreenOnSettingUseCase = Inject.instance(),
) : ViewModel() {

    val uiState: StateFlow<AppUiState> = combine(
        themeRepository.themeData,
        keepScreenOnSettingUseCase(),
    ) { themeData, isKeepScreenOn ->
        AppUiState.Success(themeData, isKeepScreenOn)
    }.stateIn(
        scope = viewModelScope,
        started = SharingStarted.Lazily,
        initialValue = AppUiState.Loading
    )

}

sealed interface AppUiState {
    data object Loading : AppUiState
    data class Success(val themeData: ThemeData, val isKeepScreenOn: Boolean) : AppUiState
}
