package com.timemeasurer.app.feature.timers_statistics

import androidx.lifecycle.viewModelScope
import com.timemeasurer.app.core.common.di.Inject
import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.domain.timer.GetTimersStatisticsUseCase
import com.timemeasurer.app.core.ui.ext.toStringResource
import com.timemeasurer.app.core.ui.viewmodels.UiState
import com.timemeasurer.app.core.ui.viewmodels.UiStateViewModel
import com.timemeasurer.app.feature.timers_statistics.models.TimersStatisticsActions
import com.timemeasurer.app.feature.timers_statistics.models.TimersStatisticsEvents
import com.timemeasurer.app.feature.timers_statistics.models.TimersStatisticsUiModel
import com.timemeasurer.app.feature.timers_statistics.models.toStatisticsItem
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.catch
import kotlinx.coroutines.flow.emitAll
import kotlinx.coroutines.flow.flow
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.flow.stateIn

class TimersStatisticsViewModel(
    private val getTimersStatisticsUseCase: GetTimersStatisticsUseCase = Inject.instance(),
) : UiStateViewModel<TimersStatisticsUiModel, TimersStatisticsActions, TimersStatisticsEvents>(
    initialAction = TimersStatisticsActions.None
) {

    override val state: StateFlow<UiState<TimersStatisticsUiModel>> = flow {
        emitAll(getTimersStatisticsUseCase())
    }.map { result ->
        when (result) {
            is Result.Loading -> UiState.Loading
            is Result.Error -> UiState.Error(result.exception)
            is Result.Success -> {
                val items = result.data.map { it.toStatisticsItem }
                if (items.isEmpty()) UiState.Empty
                else UiState.Success(TimersStatisticsUiModel(items = items))
            }
        }
    }
    .catch { error ->
        println("TimersStatisticsViewModel() - state error: $error")
        setAction(TimersStatisticsActions.ShowError(error.toStringResource))
    }
    .stateIn(
        scope = viewModelScope,
        started = SharingStarted.Lazily,
        initialValue = UiState.Loading
    )

    override fun setEvent(item: TimersStatisticsEvents) {
        when (item) {
            is TimersStatisticsEvents.None -> setAction(TimersStatisticsActions.None)
            is TimersStatisticsEvents.Load -> { /* state is reactive, no action needed */ }
        }
    }
}
