package com.timemeasurer.app.core.domain.stopwatch

import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.data.repositories.stopwatch_laps.StopwatchLapsRepository
import com.timemeasurer.app.core.model.stopwatch.StopwatchLapModel
import com.timemeasurer.app.core.model.stopwatch.StopwatchLapsModel
import com.timemeasurer.app.core.model.stopwatch.durationMs
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.flowOn
import kotlinx.coroutines.flow.map

class GetAllLapsByStopwatchIdUseCase(
    private val stopwatchLapsRepository: StopwatchLapsRepository,
    private val dispatcher: CoroutineDispatcher,
) {
    suspend operator fun invoke(stopwatchId: Long): Flow<Result<StopwatchLapsModel>> =
        stopwatchLapsRepository.getAllLapsByStopwatchId(stopwatchId)
            .map { result ->
                when (result) {
                    is Result.Error -> return@map result
                    is Result.Loading -> return@map result
                    is Result.Success<List<StopwatchLapModel>> -> {
                        val laps = result.data.toMutableList()
                        var minLapModel: StopwatchLapModel? = null
                        var maxLapModel: StopwatchLapModel? = null
                        var totalTime = 0L

                        for (index in laps.indices) {
                            val lapTime = laps[index].durationMs()
                            totalTime += lapTime
                            laps[index] = laps[index].copy(totalTimeFromStart = totalTime)

                            if (index != laps.lastIndex) {
                                val minLap = minLapModel
                                if (minLap == null || (lapTime > 0 && lapTime < minLap.durationMs())) {
                                    minLapModel = laps[index]
                                }
                                val maxLap = maxLapModel
                                if (maxLap == null || (lapTime > 0 && lapTime > maxLap.durationMs())) {
                                    maxLapModel = laps[index]
                                }
                            }
                        }

                        val lapsStr = laps.joinToString(separator = ", ") { "$it" }
                        println("GetAllLapsByStopwatchIdUseCase() - laps: ${laps.size}, $lapsStr")
                        println("GetAllLapsByStopwatchIdUseCase() - min, max: $minLapModel, $maxLapModel")

                        Result.Success(StopwatchLapsModel(
                            laps = laps.toList(),
                            minLap = minLapModel,
                            maxLap = maxLapModel,
                            totalTime = totalTime
                        ))
                    }
                }
            }
            .flowOn(dispatcher)
}
