package com.timemeasurer.app.core.domain.stopwatch

import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.model.stopwatch.StopwatchGraphType
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.withContext

class UpdateStopwatchGraphTypeUseCase(
    private val getStopwatchByIdUseCase: GetStopwatchByIdUseCase,
    private val updateStopwatchUseCase: UpdateStopwatchUseCase,
    private val dispatcher: CoroutineDispatcher,
) {
    suspend operator fun invoke(stopwatchId: Long, graphType: StopwatchGraphType): Result<Long> =
        withContext(dispatcher) {
            val stopwatchResult = getStopwatchByIdUseCase(stopwatchId).first { it !is Result.Loading }

            when (stopwatchResult) {
                is Result.Loading -> Result.Error(error = "Unexpected loading state")
                is Result.Error -> Result.Error(stopwatchResult.exception, stopwatchResult.error)
                is Result.Success -> {
                    val stopwatch = stopwatchResult.data
                        ?: return@withContext Result.Error(error = "Stopwatch not found")

                    val updatedSettings = stopwatch.settings.copy(graphType = graphType)
                    val updatedStopwatch = stopwatch.copy(settings = updatedSettings)
                    updateStopwatchUseCase(updatedStopwatch)
                }
            }
        }
}
