package com.timemeasurer.app.core.common.time

import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock

class ElapsedTimer(private val clock: MonotonicClock) {
    private val mutex = Mutex()
    private var totalMs: Long = 0
    private var startMs: Long = -1

    suspend fun elapsed(): Long = mutex.withLock {
        if (startMs < 0) totalMs else totalMs + clock.nowMs() - startMs
    }

    suspend fun start(now: Long = clock.nowMs()) {
        mutex.withLock { startMs = now }
    }

    suspend fun pause(now: Long = clock.nowMs()): Long = mutex.withLock {
        if (startMs >= 0) {
            totalMs += now - startMs
            startMs = -1
        }
        totalMs
    }

    suspend fun restart(now: Long = clock.nowMs()) {
        mutex.withLock {
            totalMs = 0
            startMs = now
        }
    }

    suspend fun reset() {
        mutex.withLock {
            totalMs = 0
            startMs = -1
        }
    }

    suspend fun add(amount: Long) {
        mutex.withLock { totalMs += amount }
    }
}
