package com.timemeasurer.app.feature.timer_settings

import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.heightIn
import androidx.compose.runtime.Composable
import androidx.compose.runtime.getValue
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import androidx.lifecycle.compose.collectAsStateWithLifecycle
import androidx.lifecycle.viewmodel.compose.viewModel
import com.timemeasurer.app.core.model.timer.TimerSettingsEvents
import com.timemeasurer.app.core.resources.Res
import com.timemeasurer.app.core.resources.apply
import com.timemeasurer.app.core.resources.cancel
import com.timemeasurer.app.core.resources.timer_settings
import com.timemeasurer.app.core.ui.viewmodels.LocalSnackbarHost
import com.timemeasurer.app.core.ui.widgets.GradientAlertDialog
import com.timemeasurer.app.feature.timer_settings.widgets.TimerSettingsContent
import org.jetbrains.compose.resources.stringResource

@Composable
internal fun TimerSettingsDialog(
    timerId: Long? = null,
    onDismiss: () -> Unit,
    viewModel: TimerSettingsViewModel = viewModel { TimerSettingsViewModel() },
) {
    val state by viewModel.state.collectAsStateWithLifecycle()
    val action by viewModel.action.collectAsStateWithLifecycle()

    remember { viewModel.setEvent(TimerSettingsEvents.Load(timerId)) }

    val snackbarHost = LocalSnackbarHost.current
    val onEvent: (TimerSettingsEvents) -> Unit = remember(viewModel) {{ viewModel.setEvent(it) }}

    TimerSettingsActionsHandler(
        action = action,
        snackbarHost = snackbarHost,
        onDismiss = onDismiss,
        onEvent = onEvent,
    )

    GradientAlertDialog(
        onDismissRequest = onDismiss,
        title = stringResource(Res.string.timer_settings),
        content = {
            Box(modifier = Modifier.heightIn(max = 300.dp)) {
                TimerSettingsContent(
                    state = state,
                    onEvent = onEvent,
                )
            }
        },
        confirmText = stringResource(Res.string.apply),
        dismissText = stringResource(Res.string.cancel),
        onConfirm = { onEvent(TimerSettingsEvents.Apply) },
        onDismissClick = onDismiss,
    )
}
