package com.timemeasurer.app.core.data.repositories.theme

import com.timemeasurer.app.core.datastore.themes.ThemesSource
import com.timemeasurer.app.core.model.DarkThemeConfig
import com.timemeasurer.app.core.model.ThemeColor
import com.timemeasurer.app.core.model.ThemeData
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.flow.Flow

internal class ThemeRepositoryImpl(
    private val themesSource: ThemesSource,
    private val coroutineDispatcher: CoroutineDispatcher
) : ThemeRepository {

    override val themeData: Flow<ThemeData> = themesSource.themeData

    override suspend fun setThemeColor(themeColor: ThemeColor) = themesSource.setThemeColor(themeColor)

    override suspend fun setDarkThemeConfig(darkThemeConfig: DarkThemeConfig) = themesSource.setDarkThemeConfig(darkThemeConfig)

    override suspend fun setGradientBackgroundEnabled(enabled: Boolean) = themesSource.setGradientBackgroundEnabled(enabled)

    override suspend fun setGradientEndColor(color: ThemeColor) = themesSource.setGradientEndColor(color)

}
