package com.timemeasurer.app.core.domain.timer

import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.data.repositories.timers.TimersRepository
import com.timemeasurer.app.core.model.timer.TimerModel
import com.timemeasurer.app.core.model.timer.TimerSettingsModel
import kotlinx.coroutines.CoroutineDispatcher
import kotlin.time.ExperimentalTime

@OptIn(ExperimentalTime::class)
class CreateNewTimerUseCase(
    private val timersRepository: TimersRepository,
    private val dispatcher: CoroutineDispatcher,
) {
    suspend operator fun invoke(
        name: String,
        settings: TimerSettingsModel = TimerSettingsModel()
    ): Result<TimerModel> =
        timersRepository.createTimer(name = name, settings = settings)

}
