@Composable
fun IconPickerInputDialog(
    title: String,
    initialText: String,
    initialIconId: String,
    confirmText: String,
    onConfirm: (name: String, iconId: String) -> Unit,
    onDismiss: () -> Unit,
    dismissText: String? = null,
    nameError: StringResource? = null,
    onValidateName: (String) -> Unit = {},
    maxNameLength: Int = 60,
) {
    var textFieldValue by remember(initialText) {
        mutableStateOf(
            TextFieldValue(
                text = initialText,
                selection = TextRange(0, initialText.length)
            )
        )
    }
    var selectedIconId by remember(initialIconId) { mutableStateOf(initialIconId) }

    GradientAlertDialog(
        onDismissRequest = onDismiss,
        title = title,
        content = {
            Column(modifier = Modifier.padding(horizontal = 24.dp)) {
                TextField(
                    value = textFieldValue,
                    onValueChange = { if (it.text.length <= maxNameLength) textFieldValue = it },
                    isError = nameError != null,
                    singleLine = true,
                    textStyle = MaterialTheme.typography.titleLarge.copy(
                        fontWeight = FontWeight.W400
                    ),
                    modifier = Modifier
                        .fillMaxWidth(),
                )
                if (nameError != null) {
                    Text(
                        text = stringResource(nameError),
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.error,
                        modifier = Modifier.padding(start = 16.dp, top = 4.dp),
                    )
                }
                IconPickerGrid(
                    selectedIconId = selectedIconId,
                    onIconSelected = { selectedIconId = it },
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(top = 16.dp),
                )
            }
        },
        confirmText = confirmText,
        onConfirm = { onConfirm(textFieldValue.text, selectedIconId) },
        dismissText = dismissText ?: stringResource(Res.string.close),
        onDismissClick = onDismiss,
    )
}

@Composable
private fun IconPickerGrid(
    selectedIconId: String,
    onIconSelected: (String) -> Unit,
    modifier: Modifier = Modifier,
) {
    val rows = listOf(
        SportIconSet.set.icons,
        WorkIconSet.set.icons,
        RestIconSet.set.icons,
        EntertainmentIconSet.set.icons,
    )

    Column(
        modifier = modifier,
        verticalArrangement = Arrangement.spacedBy(4.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        rows.forEach { rowIcons ->
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(4.dp, Alignment.CenterHorizontally),
            ) {
                rowIcons.forEach { appIcon ->
                    IconPickerItem(
                        iconModel = appIcon,
                        isSelected = appIcon.id == selectedIconId,
                        onClick = { onIconSelected(appIcon.id) },
                    )
                }
            }
        }
    }
}

@Composable
private fun IconPickerItem(
    iconModel: IconModel,
    isSelected: Boolean,
    onClick: () -> Unit,
    modifier: Modifier = Modifier,
) {
    val borderColor = if (isSelected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.outlineVariant
    val backgroundColor = if (isSelected) MaterialTheme.colorScheme.primaryContainer else MaterialTheme.colorScheme.surface

    Box(
        modifier = modifier
            .size(30.dp)
            .clickable(onClick = onClick)
            .background(backgroundColor, RoundedCornerShape(8.dp))
            .border(1.dp, borderColor, RoundedCornerShape(8.dp)),
        contentAlignment = Alignment.Center,
    ) {
        Icon(
            imageVector = iconModel.icon,
            contentDescription = null,
            modifier = Modifier.size(20.dp),
            tint = if (isSelected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurfaceVariant,
        )
    }
}

