package com.timemeasurer.app.feature.timers.models


sealed interface TimerEvents {
    data object None : TimerEvents
    data class StartPause(val timerId: Long) : TimerEvents
    data class ShowResetDialog(val timerId: Long) : TimerEvents
    data class Reset(val timerId: Long) : TimerEvents
    data class Skip(val timerId: Long) : TimerEvents
    data class Stop(val timerId: Long) : TimerEvents

    data class Create(val name: String, val iconId: String = "") : TimerEvents
    data object ShowCreateDialog : TimerEvents
    data object ToggleSpeedDial : TimerEvents
    data class ShowRenameDialog(val currentPage: Int) : TimerEvents
    data class Rename(val timerId: Long, val name: String, val iconId: String = "") : TimerEvents
    data class ShowDeleteDialog(val currentPage: Int) : TimerEvents
    data class Delete(val timerId: Long) : TimerEvents
    data class ShowSettings(val currentPage: Int) : TimerEvents
    data object ShowStatistics : TimerEvents
    data class TimerDefaultName(val baseName: String) : TimerEvents
    data class OnPageSelected(val page: Int) : TimerEvents
    data class ValidateCreateName(val name: String) : TimerEvents
    data class ValidateRenameName(val name: String) : TimerEvents
}