package com.timemeasurer.app.core.data.repositories.stopwatches

import app.cash.sqldelight.async.coroutines.awaitAsList
import app.cash.sqldelight.async.coroutines.awaitAsOneOrNull
import app.cash.sqldelight.coroutines.asFlow
import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.common.result.startLoading
import com.timemeasurer.app.core.data.database.AppDatabase
import com.timemeasurer.app.core.data.model.entitiesToStopwatchesModels
import com.timemeasurer.app.core.data.model.toEncodeString
import com.timemeasurer.app.core.data.model.toStopwatchModel
import com.timemeasurer.app.core.data.model.toStopwatchesEntity
import com.timemeasurer.app.core.model.stopwatch.StopwatchModel
import com.timemeasurer.app.core.model.stopwatch.StopwatchSettingsModel
import com.timemeasurer.app.core.remote_services.CrashlyticsService
import com.timemeasurer.app.core.remote_services.NoOpCrashlyticsService
import data.StopwatchesEntity
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.catch
import kotlinx.coroutines.flow.distinctUntilChanged
import kotlinx.coroutines.flow.filterNot
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.flow.onStart

internal class StopwatchesRepositoryImpl(
    private val database: AppDatabase,
    private val scope: CoroutineScope,
    private val crashlytics: CrashlyticsService = NoOpCrashlyticsService()
) : StopwatchesRepository {

    override suspend fun getStopwatches(): Flow<Result<List<StopwatchModel>>> {
        val dbFlow = database.db().stopwatchesQueries.selectAll()
            .asFlow()
            .map { it.awaitAsList() }
            .map<List<StopwatchesEntity>, Result<List<StopwatchModel>>> {
                Result.Success(it.entitiesToStopwatchesModels())
            }
            .onStart { emit(Result.Loading) }
            .catch {
                crashlytics.log("StopwatchesRepositoryImpl() - getStopwatches()")
                crashlytics.recordException(it)
                println("StopwatchesRepositoryImpl() - getStopwatches() - error: $it")
                emit(Result.Error(it))
            }

        return dbFlow.startLoading()
            .distinctUntilChanged()
    }

    override suspend fun getStopwatchesById(sinceId: Long, count: Long): Flow<Result<List<StopwatchModel>>> {
        val dbFlow = database.db().stopwatchesQueries.selectSinceId(sinceId = sinceId, count = count)
            .asFlow()
            .map { it.awaitAsList() }
            .filterNot { it.isEmpty() }
            .map<List<StopwatchesEntity>, Result<List<StopwatchModel>>> {
                Result.Success(it.entitiesToStopwatchesModels())
            }
            .onStart { emit(Result.Loading) }
            .catch {
                crashlytics.log("StopwatchesRepositoryImpl() - getStopwatchesById()")
                crashlytics.recordException(it)
                println("StopwatchesRepositoryImpl() - getStopwatchesById() - error: $it")
                emit(Result.Error(it))
            }

        return dbFlow.startLoading()
            .distinctUntilChanged()
    }

    override suspend fun getStopwatchById(id: Long): Flow<Result<StopwatchModel?>> {
        val dbFlow = database.db().stopwatchesQueries.selectById(stopwatchId = id)
            .asFlow()
            .map { it.awaitAsOneOrNull() }
            .map<StopwatchesEntity?, Result<StopwatchModel?>> {
                Result.Success(it?.toStopwatchModel())
            }
            .onStart { emit(Result.Loading) }
            .catch {
                crashlytics.log("StopwatchesRepositoryImpl() - getStopwatchById()")
                crashlytics.recordException(it)
                println("StopwatchesRepositoryImpl() - getStopwatchById() - error: $it")
                emit(Result.Error(it))
            }

        return dbFlow.startLoading()
            .distinctUntilChanged()
    }

    override suspend fun getStopwatchesByName(name: String): Flow<Result<List<StopwatchModel>>> {
        val dbFlow = database.db().stopwatchesQueries.selectByName(name = name)
            .asFlow()
            .map { it.awaitAsList() }
            .filterNot { it.isEmpty() }
            .map<List<StopwatchesEntity>, Result<List<StopwatchModel>>> {
                Result.Success(it.entitiesToStopwatchesModels())
            }
            .onStart { emit(Result.Loading) }
            .catch {
                crashlytics.log("StopwatchesRepositoryImpl() - getStopwatchesByName()")
                crashlytics.recordException(it)
                println("StopwatchesRepositoryImpl() - getStopwatchesByName() - error: $it")
                emit(Result.Error(it))
            }

        return dbFlow.startLoading()
            .distinctUntilChanged()
    }

    override suspend fun updateStopwatch(item: StopwatchModel): Result<Long> {
        val result = runCatching {
            database.db().stopwatchesQueries.insertOrUpdate(item.toStopwatchesEntity())
        }
        result.exceptionOrNull()?.let {
            crashlytics.log("StopwatchRepositoryImpl() - updateStopwatch()")
            crashlytics.recordException(it)
        }

        val rowsCount = result.getOrNull() ?: 0L
        println("StopwatchRepositoryImpl() - updateStopwatch(): ${rowsCount}, ${result.exceptionOrNull()}")
        return if (rowsCount > 0) Result.Success(rowsCount)
        else Result.Error(exception = result.exceptionOrNull(), error = "Rows updated is 0")
    }

    override suspend fun renameStopwatch(stopwatchId: Long, newName: String, iconId: String): Result<Long> {
        val result = runCatching {
            val entity = database.db().stopwatchesQueries.selectById(stopwatchId).awaitAsOneOrNull()
                ?: throw IllegalStateException("Stopwatch not found: $stopwatchId")

            val model = entity.toStopwatchModel()
            val updated = model.copy(
                name = newName,
                settings = model.settings.copy(iconId = iconId)
            ).toStopwatchesEntity()

            database.db().stopwatchesQueries.updateNameAndSettingsById(
                name = updated.name,
                settings = updated.settings,
                stopwatchId = stopwatchId
            )
        }
        result.exceptionOrNull()?.let {
            crashlytics.log("StopwatchRepositoryImpl() - renameStopwatch()")
            crashlytics.recordException(it)
        }

        val rowsCount = result.getOrNull() ?: 0L
        println("StopwatchRepositoryImpl() - renameStopwatch(): ${rowsCount}, ${result.exceptionOrNull()}")
        return if (rowsCount > 0) Result.Success(rowsCount)
        else Result.Error(exception = result.exceptionOrNull(), error = "Rows updated is 0")
    }

    override suspend fun deleteStopwatch(stopwatchId: Long): Result<Long> {
        val result = runCatching {
            database.db().stopwatchesQueries.deleteById(stopwatchId)
        }
        result.exceptionOrNull()?.let {
            crashlytics.log("StopwatchRepositoryImpl() - deleteStopwatch()")
            crashlytics.recordException(it)
        }

        val rowsCount = result.getOrNull() ?: 0L
        println("StopwatchRepositoryImpl() - deleteStopwatch(): ${rowsCount}, ${result.exceptionOrNull()}")
        return if (rowsCount > 0) Result.Success(rowsCount)
        else Result.Error(exception = result.exceptionOrNull(), error = "Rows deleted is 0")
    }

    override suspend fun createStopwatch(name: String, settings: StopwatchSettingsModel): Result<StopwatchModel> {
        val result = runCatching {
            database.db().stopwatchesQueries.insertAndReturn(
                name = name,
                settings = settings.toEncodeString()
            ).awaitAsOneOrNull()
        }
        result.exceptionOrNull()?.let {
            crashlytics.log("StopwatchRepositoryImpl() - createStopwatch()")
            crashlytics.recordException(it)
        }

        val stopwatch = result.getOrNull()
        println("StopwatchRepositoryImpl() - createStopwatch(): ${stopwatch}, ${result.exceptionOrNull()}")
        return if (stopwatch != null) Result.Success(stopwatch.toStopwatchModel())
        else Result.Error(exception = result.exceptionOrNull(), error = "Create stopwatch fail")
    }
}
