package com.timemeasurer.app.core.domain.stopwatch

import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.data.repositories.stopwatches.StopwatchesRepository
import com.timemeasurer.app.core.model.stopwatch.StopwatchModel
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.withContext

class GetStopwatchesUseCase(
    private val stopwatchesRepository: StopwatchesRepository,
    private val dispatcher: CoroutineDispatcher,
) {

    suspend operator fun invoke(): Flow<Result<List<StopwatchModel>>> = withContext(dispatcher) {
        stopwatchesRepository.getStopwatches()
    }
}
