package com.timemeasurer.app.core.`data`.`data`

import `data`.Stopwatch_lapsQueries
import `data`.StopwatchesQueries
import `data`.Timer_sessionsQueries
import `data`.TimersQueries
import app.cash.sqldelight.SuspendingTransacterImpl
import app.cash.sqldelight.db.AfterVersion
import app.cash.sqldelight.db.QueryResult
import app.cash.sqldelight.db.SqlDriver
import app.cash.sqldelight.db.SqlSchema
import com.timemeasurer.app.core.`data`.Database
import kotlin.Long
import kotlin.Unit
import kotlin.reflect.KClass

internal val KClass<Database>.schema: SqlSchema<QueryResult.AsyncValue<Unit>>
  get() = DatabaseImpl.Schema

internal fun KClass<Database>.newInstance(driver: SqlDriver): Database = DatabaseImpl(driver)

private class DatabaseImpl(
  driver: SqlDriver,
) : SuspendingTransacterImpl(driver),
    Database {
  override val stopwatch_lapsQueries: Stopwatch_lapsQueries = Stopwatch_lapsQueries(driver)

  override val stopwatchesQueries: StopwatchesQueries = StopwatchesQueries(driver)

  override val timer_sessionsQueries: Timer_sessionsQueries = Timer_sessionsQueries(driver)

  override val timersQueries: TimersQueries = TimersQueries(driver)

  public object Schema : SqlSchema<QueryResult.AsyncValue<Unit>> {
    override val version: Long
      get() = 1

    override fun create(driver: SqlDriver): QueryResult.AsyncValue<Unit> = QueryResult.AsyncValue {
      driver.execute(null, """
          |CREATE TABLE IF NOT EXISTS StopwatchLapsEntity(
          |    id INTEGER PRIMARY KEY AUTOINCREMENT,
          |    stopwatchId INTEGER NOT NULL,
          |    lap INTEGER NOT NULL,
          |    time INTEGER NOT NULL
          |)
          """.trimMargin(), 0).await()
      driver.execute(null, """
          |CREATE TABLE IF NOT EXISTS StopwatchesEntity(
          |    id INTEGER PRIMARY KEY AUTOINCREMENT,
          |    name TEXT NOT NULL UNIQUE,
          |    settings TEXT NOT NULL
          |)
          """.trimMargin(), 0).await()
      driver.execute(null, """
          |CREATE TABLE IF NOT EXISTS TimersSessionsEntity(
          |    id INTEGER PRIMARY KEY AUTOINCREMENT,
          |    timerId INTEGER NOT NULL,
          |    session INTEGER NOT NULL,
          |    type TEXT NOT NULL,
          |    startedAt INTEGER NOT NULL,
          |    endAt INTEGER NOT NULL,
          |    UNIQUE(timerId, startedAt)
          |)
          """.trimMargin(), 0).await()
      driver.execute(null, """
          |CREATE TABLE IF NOT EXISTS TimersEntity(
          |    id INTEGER PRIMARY KEY AUTOINCREMENT,
          |    name TEXT NOT NULL UNIQUE,
          |    settings TEXT NOT NULL
          |)
          """.trimMargin(), 0).await()
    }

    override fun migrate(
      driver: SqlDriver,
      oldVersion: Long,
      newVersion: Long,
      vararg callbacks: AfterVersion,
    ): QueryResult.AsyncValue<Unit> = QueryResult.AsyncValue {
    }
  }
}
