package com.timemeasurer.app

import androidx.compose.material3.windowsizeclass.WindowWidthSizeClass
import androidx.compose.runtime.Composable
import androidx.compose.runtime.Stable
import androidx.compose.runtime.remember
import androidx.compose.ui.platform.LocalWindowInfo
import androidx.navigation3.runtime.NavBackStack
import androidx.navigation3.runtime.NavKey
import com.timemeasurer.app.core.navigation.AppRoute
import com.timemeasurer.app.core.navigation.AppRouter
import com.timemeasurer.app.core.navigation.TopLevelDestination
import com.timemeasurer.app.core.navigation.rememberAppNavBackStack
import com.timemeasurer.app.core.ui.ext.windowSizeClass

@Composable
fun rememberAppState(
    backStack: NavBackStack<NavKey> = rememberAppNavBackStack(),
): AppState {
    return remember(backStack) {
        AppState(backStack = backStack)
    }
}

@Stable
class AppState(
    val backStack: NavBackStack<NavKey>,
) : AppRouter {

    @Suppress("UNCHECKED_CAST")
    override val currentRoute: AppRoute? get() = backStack.lastOrNull() as? AppRoute

    override val currentTopLevelDestination: TopLevelDestination?
        get() {
            for (i in backStack.indices.reversed()) {
                val route = backStack[i] as? AppRoute ?: continue
                when (route) {
                    is AppRoute.Timers,
                    is AppRoute.TimerSettings,
                    is AppRoute.TimersStatistics -> return TopLevelDestination.TIMERS
                    is AppRoute.Stopwatches,
                    is AppRoute.StopwatchesStatistics -> return TopLevelDestination.STOPWATCHES
                    is AppRoute.Settings -> return TopLevelDestination.SETTINGS
                    else -> continue
                }
            }
            return null
        }

    val isSplashVisible: Boolean
        get() = currentRoute is AppRoute.Splash || currentRoute == null

    val isAppFocused: Boolean
        @Composable get() = LocalWindowInfo.current.isWindowFocused

    val shouldShowBottomBar: Boolean
        @Composable get() {
            val widthSizeClass = windowSizeClass.widthSizeClass
            val isCompact = widthSizeClass == WindowWidthSizeClass.Medium || widthSizeClass == WindowWidthSizeClass.Compact
            return isCompact
        }

    val shouldShowNavRail: Boolean
        @Composable get() = !shouldShowBottomBar

    val isExpanded: Boolean
        @Composable get() = windowSizeClass.widthSizeClass == WindowWidthSizeClass.Expanded

    val topLevelDestinations: List<TopLevelDestination> = TopLevelDestination.entries

    override fun navigateToTopLevelDestination(destination: TopLevelDestination) {
        val targetRoute: AppRoute = when (destination) {
            TopLevelDestination.TIMERS -> AppRoute.Timers
            TopLevelDestination.STOPWATCHES -> AppRoute.Stopwatches
            TopLevelDestination.SETTINGS -> AppRoute.Settings
        }

        if (currentTopLevelDestination == destination && currentRoute == targetRoute) return

        if (currentTopLevelDestination == destination) {
            val idx = backStack.indexOfLast { (it as? AppRoute) == targetRoute }
            if (idx >= 0) {
                repeat(backStack.size - 1 - idx) { backStack.removeLastOrNull() }
            }
        } else {
            backStack.clear()
            backStack.add(targetRoute)
        }
    }

    override fun navigateTo(route: AppRoute) {
        backStack.add(route)
    }

    override fun goBack(): Boolean {
        if (backStack.size > 1) {
            backStack.removeLastOrNull()
            return true
        }
        return false
    }

    override fun removeIf(predicate: (AppRoute) -> Boolean) {
        val toRemove = backStack.filter { (it as? AppRoute)?.let(predicate) == true }
        backStack.removeAll(toRemove)
    }
}
