package com.timemeasurer.app.core.data.model

import com.timemeasurer.app.core.model.stopwatch.StopwatchLapModel
import data.StopwatchLapsEntity

fun StopwatchLapsEntity.toStopwatchLapModel() = StopwatchLapModel(
    id = id,
    stopwatchId = stopwatchId,
    lapNumber = lap.toInt(),
    time = time,
)

fun List<StopwatchLapsEntity>.entitiesToStopwatchLapsModels() = map { it.toStopwatchLapModel() }

fun StopwatchLapModel.toStopwatchLapsEntity() = StopwatchLapsEntity(
    id = id,
    stopwatchId = stopwatchId,
    lap = lapNumber.toLong(),
    time = time,
)

fun List<StopwatchLapModel>.modelsToStopwatchLapsEntities() = map { it.toStopwatchLapsEntity() }
