package com.timemeasurer.app.core.player.sound

class JsSoundPlayer : SoundPlayer {
    override fun play(soundId: String, vibrate: Boolean) {
        if (soundId == PredefinedSound.NONE.id) return
        if (vibrate) vibrate()
    }

    override fun stop() {}

    override fun vibrate(durationMs: Long) {}
}
