package com.timemeasurer.app.feature.timers.models

import com.timemeasurer.app.core.domain.common.ValidateNameUseCase
import com.timemeasurer.app.core.model.icon.DefaultIconIds
import org.jetbrains.compose.resources.StringResource


sealed interface TimerActions {
    data object None : TimerActions
    data class ShowError(val error: StringResource) : TimerActions

    data class ShowCreateTimerDialog(
        val isDialogVisible: Boolean = false,
        val timerId: Long = 1L,
        val iconId: String = DefaultIconIds.TIMER,
        val nameError: StringResource? = null,
        val maxNameLength: Int = ValidateNameUseCase.MAX_LENGTH,
    ) : TimerActions

    data class ShowRenameTimerDialog(
        val isDialogVisible: Boolean = false,
        val timerId: Long = 0L,
        val currentName: String = "",
        val iconId: String = "",
        val nameError: StringResource? = null,
        val maxNameLength: Int = ValidateNameUseCase.MAX_LENGTH,
    ) : TimerActions

    data class ShowDeleteTimerDialog(
        val isDialogVisible: Boolean = false,
        val timerId: Long = 0L,
        val currentName: String = ""
    ) : TimerActions

    data class ShowResetTimerDialog(
        val isDialogVisible: Boolean = false,
        val timerId: Long = 0L,
    ) : TimerActions

    data class OpenTimerSettings(val timerId: Long) : TimerActions
    data object OpenStatistics : TimerActions
}