package com.timemeasurer.app.core.navigation

import androidx.navigation3.runtime.NavKey
import kotlinx.serialization.Serializable

@Serializable
sealed interface AppRoute : NavKey {
    @Serializable data object Splash : AppRoute
    @Serializable data object Timers : AppRoute
    @Serializable data object Stopwatches : AppRoute
    @Serializable data object Settings : AppRoute
    @Serializable data object Themes : AppRoute
    @Serializable data class TimerSettings(val timerId: Long? = null) : AppRoute
    @Serializable data class TimerSettingsDialog(val timerId: Long? = null) : AppRoute
    @Serializable data object TimersStatistics : AppRoute
    @Serializable data object StopwatchesStatistics : AppRoute
}
