package com.timemeasurer.app.feature.stopwatches.models

sealed interface StopwatchEvents {
    data object None : StopwatchEvents
    data class StartStop(val stopwatchId: Long) : StopwatchEvents
    data class Reset(val stopwatchId: Long) : StopwatchEvents
    data class ShowResetDialog(val stopwatchId: Long) : StopwatchEvents
    data class ConfirmReset(val stopwatchId: Long) : StopwatchEvents
    data class Lap(val stopwatchId: Long) : StopwatchEvents

    data class Create(val name: String, val iconId: String = "") : StopwatchEvents
    data object ShowCreateDialog : StopwatchEvents
    data object ToggleSpeedDial : StopwatchEvents
    data class ShowRenameDialog(val currentPage: Int) : StopwatchEvents
    data class Rename(val stopwatchId: Long, val name: String, val iconId: String = "") : StopwatchEvents
    data class ShowDeleteDialog(val currentPage: Int) : StopwatchEvents
    data class Delete(val stopwatchId: Long) : StopwatchEvents
    data object ShowStatistics : StopwatchEvents
    data class StopwatchDefaultName(val baseName: String) : StopwatchEvents

    data class OnPageSelected(val page: Int) : StopwatchEvents
    data class ValidateCreateName(val name: String) : StopwatchEvents
    data class ValidateRenameName(val name: String) : StopwatchEvents
}
