package com.timemeasurer.app.feature.stopwatches.navigation

import androidx.compose.foundation.layout.padding
import androidx.compose.material3.adaptive.ExperimentalMaterial3AdaptiveApi
import androidx.compose.material3.windowsizeclass.WindowWidthSizeClass
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import androidx.navigation3.runtime.EntryProviderScope
import androidx.navigation3.runtime.NavKey
import com.timemeasurer.app.core.navigation.AppRoute
import com.timemeasurer.app.core.navigation.AppRouter
import com.timemeasurer.app.core.navigation.CustomListDetailKeys
import com.timemeasurer.app.core.resources.Res
import com.timemeasurer.app.core.resources.empty
import com.timemeasurer.app.core.ui.ext.windowSizeClass
import com.timemeasurer.app.core.ui.icon.MainIconSet
import com.timemeasurer.app.core.ui.viewmodels.TopBarNavigationViewModel
import com.timemeasurer.app.core.ui.widgets.RoundedPlaceholderWidget
import com.timemeasurer.app.feature.stopwatches.StopwatchesScreen
import org.jetbrains.compose.resources.stringResource
import org.kodein.di.compose.viewmodel.rememberViewModel

@OptIn(ExperimentalMaterial3AdaptiveApi::class)
fun EntryProviderScope<NavKey>.stopwatchesEntry(
    appRouter: AppRouter,
) {
    entry<AppRoute.Stopwatches>(
        metadata = CustomListDetailKeys.listPane(
            detailPlaceholder = {
                RoundedPlaceholderWidget(
                    header = stringResource(Res.string.empty),
                    image = MainIconSet.search.icon,
                    modifier = Modifier.padding(all = 8.dp)
                )
            }
        )
    ) {
        val isExpanded = windowSizeClass.widthSizeClass == WindowWidthSizeClass.Expanded
        val topBarNavigationViewModel: TopBarNavigationViewModel by rememberViewModel()
        StopwatchesScreen(
            isExpanded = isExpanded,
            onStatisticsClick = {
                if (!isExpanded) {
                    appRouter.navigateTo(AppRoute.StopwatchesStatistics)
                }
            },
            onStopwatchSelected = {
                if (isExpanded) {
                    appRouter.removeIf { it is AppRoute.StopwatchesStatistics }
                    appRouter.navigateTo(AppRoute.StopwatchesStatistics)
                }
            },
            topBarNavigationViewModel = topBarNavigationViewModel,
        )
    }
}
