package com.timemeasurer.app.core.domain.stopwatch

import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.data.repositories.stopwatches.StopwatchesRepository
import com.timemeasurer.app.core.model.stopwatch.StopwatchModel
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.withContext

class UpdateStopwatchUseCase(
    private val stopwatchesRepository: StopwatchesRepository,
    private val ioScope: CoroutineScope,
    private val ioDispatcher: CoroutineDispatcher,
) {
    suspend operator fun invoke(item: StopwatchModel): Result<Long> = withContext(ioDispatcher) {
        stopwatchesRepository.updateStopwatch(item)
    }

    suspend operator fun invoke(stopwatchId: Long, newName: String, iconId: String): Result<Long> = withContext(ioDispatcher) {
        stopwatchesRepository.renameStopwatch(stopwatchId, newName, iconId)
    }
}
