package com.timemeasurer.app.feature.stopwatches

import androidx.lifecycle.viewModelScope
import com.timemeasurer.app.core.common.di.Inject
import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.domain.common.NameValidationError
import com.timemeasurer.app.core.domain.common.ValidateNameUseCase
import com.timemeasurer.app.core.domain.stopwatch.StopwatchesInteractors
import com.timemeasurer.app.core.model.icon.DefaultIconIds
import com.timemeasurer.app.core.resources.Res
import com.timemeasurer.app.core.resources.timer_name_empty
import com.timemeasurer.app.core.ui.ext.toStringResource
import com.timemeasurer.app.core.ui.viewmodels.UiState
import com.timemeasurer.app.core.ui.viewmodels.UiStateViewModel
import com.timemeasurer.app.feature.stopwatches.models.DEFAULT_LOADING_STOPWATCH_ID
import com.timemeasurer.app.feature.stopwatches.models.StopwatchActions
import com.timemeasurer.app.feature.stopwatches.models.StopwatchActions.ShowCreateStopwatchDialog
import com.timemeasurer.app.feature.stopwatches.models.StopwatchActions.ShowDeleteStopwatchDialog
import com.timemeasurer.app.feature.stopwatches.models.StopwatchActions.ShowRenameStopwatchDialog
import com.timemeasurer.app.feature.stopwatches.models.StopwatchActions.ShowResetStopwatchDialog
import com.timemeasurer.app.feature.stopwatches.models.StopwatchEvents
import com.timemeasurer.app.feature.stopwatches.models.StopwatchUiTickModel
import com.timemeasurer.app.feature.stopwatches.models.StopwatchesUiModel
import com.timemeasurer.app.feature.stopwatches.models.emptyStopwatchesUiModel
import com.timemeasurer.app.feature.stopwatches.models.toStopwatchUiDataModels
import com.timemeasurer.app.feature.stopwatches.models.toStopwatchUiTickModel
import kotlinx.collections.immutable.toImmutableList
import kotlinx.coroutines.channels.BufferOverflow
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.catch
import kotlinx.coroutines.flow.combine
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.flow.stateIn

class StopwatchesViewModel(
    private val stopwatchesInteractors: StopwatchesInteractors = Inject.instance(),
) : UiStateViewModel<StopwatchesUiModel, StopwatchActions, StopwatchEvents>(
    initialAction = StopwatchActions.None
) {
    private val validateNameUseCase: ValidateNameUseCase = Inject.instance()
    private val _isSpeedDialExpanded = MutableStateFlow(false)
    private val _defaultStopwatchTickState = MutableStateFlow(StopwatchUiTickModel())
    private var _lastDialogStopwatchId: Long = 0L
    private var _lastDialogIconId: String = DefaultIconIds.STOPWATCH
    private var _lastDialogCurrentName: String = ""
    private val _defaultStopwatchName = MutableSharedFlow<String>(replay = 1, onBufferOverflow = BufferOverflow.DROP_LATEST)

    private fun NameValidationError.toResource() = when (this) {
        NameValidationError.EMPTY -> Res.string.timer_name_empty
    }

    val uiState: StateFlow<UiState<StopwatchesUiModel>> = combine(
        stopwatchesInteractors.metadataState,
        _isSpeedDialExpanded,
        _defaultStopwatchName
    ) { swState, speedDial, defaultName ->
        when (swState) {
            is Result.Error -> UiState.Error(swState.exception)
            is Result.Loading -> UiState.Success(
                emptyStopwatchesUiModel(defaultName = defaultName, isSpeedDialExpanded = speedDial)
            )
            is Result.Success -> {
                val stopwatches = swState.data.toStopwatchUiDataModels(
                    defaultName = defaultName,
                    getShowLaps = { it.laps.size > 3 },
                    getShowCurrent = { it.laps.size > 1 },
                    getShowMinMax = { it.laps.size > 2 },
                ) {
                    stopwatchesInteractors.rename(
                        stopwatchId = it.stopwatchId,
                        name = "$defaultName ${it.stopwatchId}",
                        iconId = it.iconId,
                    )
                }.toImmutableList()

                if (stopwatches.isEmpty()) {
                    UiState.Success(emptyStopwatchesUiModel(defaultName = defaultName, isSpeedDialExpanded = speedDial))
                } else {
                    UiState.Success(
                        StopwatchesUiModel(
                            stopwatches = stopwatches,
                            isSpeedDialExpanded = speedDial,
                            isDeleteVisible = swState.data.size > 1,
                        )
                    )
                }
            }
        }
    }.catch { error ->
        println("StopwatchesViewModel() - uiState error: $error")
        setAction(StopwatchActions.ShowError(error.toStringResource))
    }.stateIn(
        scope = viewModelScope,
        started = SharingStarted.Lazily,
        initialValue = UiState.Success(emptyStopwatchesUiModel())
    )

    val tickState: StateFlow<Map<Long, StateFlow<StopwatchUiTickModel>>> =
        stopwatchesInteractors.tickState
            .map { map ->
                map.mapValues { (_, tickFlow) ->
                    tickFlow.map { result ->
                        when (result) {
                            is Result.Success -> result.data.toStopwatchUiTickModel()
                            else -> StopwatchUiTickModel()
                        }
                    }.stateIn(
                        scope = viewModelScope,
                        started = SharingStarted.WhileSubscribed(5000),
                        initialValue = StopwatchUiTickModel()
                    )
                } + (DEFAULT_LOADING_STOPWATCH_ID to _defaultStopwatchTickState)
            }
            .stateIn(
                scope = viewModelScope,
                started = SharingStarted.Lazily,
                initialValue = mapOf(DEFAULT_LOADING_STOPWATCH_ID to _defaultStopwatchTickState)
            )

    override fun setEvent(item: StopwatchEvents) {
        println("setEvents($item)")
        when (item) {
            is StopwatchEvents.None -> {
                setAction(StopwatchActions.None)
                _isSpeedDialExpanded.value = false
            }
            is StopwatchEvents.ToggleSpeedDial -> _isSpeedDialExpanded.value = !_isSpeedDialExpanded.value
            is StopwatchEvents.StartStop -> stopwatchesInteractors.startStop(item.stopwatchId)
            is StopwatchEvents.Reset -> stopwatchesInteractors.reset(item.stopwatchId)
            is StopwatchEvents.ShowResetDialog -> setAction(
                ShowResetStopwatchDialog(isDialogVisible = true, stopwatchId = item.stopwatchId)
            )
            is StopwatchEvents.ConfirmReset -> {
                stopwatchesInteractors.reset(item.stopwatchId)
                setAction(ShowResetStopwatchDialog())
            }
            is StopwatchEvents.Lap -> stopwatchesInteractors.lap(item.stopwatchId)

            is StopwatchEvents.ShowCreateDialog -> {
                val nextStopwatchId = (uiState.value as? UiState.Success<StopwatchesUiModel>)?.item?.stopwatches
                    ?.maxOfOrNull { it.stopwatchId }?.plus(1) ?: 1L

                _lastDialogStopwatchId = nextStopwatchId
                _lastDialogIconId = DefaultIconIds.STOPWATCH
                setAction(
                    ShowCreateStopwatchDialog(
                        isDialogVisible = true,
                        stopwatchId = nextStopwatchId,
                        iconId = DefaultIconIds.STOPWATCH
                    )
                )
            }

            is StopwatchEvents.Create -> {
                val result = validateNameUseCase.validate(item.name)
                if (!result.isValid) {
                    setAction(
                        ShowCreateStopwatchDialog(
                            isDialogVisible = true,
                            stopwatchId = _lastDialogStopwatchId,
                            iconId = item.iconId,
                            nameError = result.error?.toResource(),
                        )
                    )
                } else {
                    stopwatchesInteractors.create(item.name, item.iconId)
                    setAction(ShowCreateStopwatchDialog())
                    _isSpeedDialExpanded.value = false
                }
            }

            is StopwatchEvents.ShowRenameDialog -> {
                val currentStopwatch = (uiState.value as? UiState.Success<StopwatchesUiModel>)?.item?.stopwatches
                    ?.getOrNull(item.currentPage) ?: return

                _lastDialogStopwatchId = currentStopwatch.stopwatchId
                _lastDialogIconId = currentStopwatch.iconId
                _lastDialogCurrentName = currentStopwatch.name
                setAction(
                    ShowRenameStopwatchDialog(
                        isDialogVisible = true,
                        stopwatchId = currentStopwatch.stopwatchId,
                        currentName = currentStopwatch.name,
                        iconId = currentStopwatch.iconId
                    )
                )
            }

            is StopwatchEvents.Rename -> {
                val result = validateNameUseCase.validate(item.name)
                if (!result.isValid) {
                    setAction(
                        ShowRenameStopwatchDialog(
                            isDialogVisible = true,
                            stopwatchId = item.stopwatchId,
                            currentName = item.name,
                            iconId = item.iconId,
                            nameError = result.error?.toResource(),
                        )
                    )
                } else {
                    stopwatchesInteractors.rename(item.stopwatchId, item.name, item.iconId)
                    setAction(ShowRenameStopwatchDialog())
                    _isSpeedDialExpanded.value = false
                }
            }

            is StopwatchEvents.ShowDeleteDialog -> {
                val currentStopwatch = (uiState.value as? UiState.Success<StopwatchesUiModel>)?.item?.stopwatches
                    ?.getOrNull(item.currentPage) ?: return

                setAction(
                    ShowDeleteStopwatchDialog(
                        isDialogVisible = true,
                        stopwatchId = currentStopwatch.stopwatchId,
                        currentName = currentStopwatch.name
                    )
                )
            }

            is StopwatchEvents.Delete -> {
                stopwatchesInteractors.delete(item.stopwatchId)
                setAction(ShowDeleteStopwatchDialog())
                _isSpeedDialExpanded.value = false
            }

            is StopwatchEvents.ShowStatistics -> {
                setAction(StopwatchActions.OpenStatistics)
            }

            is StopwatchEvents.OnPageSelected -> {
                val stopwatches = (uiState.value as? UiState.Success<StopwatchesUiModel>)?.item?.stopwatches.orEmpty()
                val activeId = stopwatches.getOrNull(item.page)?.stopwatchId ?: 0

                stopwatches.forEach { sw ->
                    stopwatchesInteractors.setVisible(sw.stopwatchId, sw.stopwatchId == activeId)
                }
            }

            is StopwatchEvents.ValidateCreateName -> {
                val result = validateNameUseCase.validate(item.name)
                setAction(
                    ShowCreateStopwatchDialog(
                        isDialogVisible = true,
                        stopwatchId = _lastDialogStopwatchId,
                        iconId = _lastDialogIconId,
                        nameError = result.error?.toResource(),
                    )
                )
            }

            is StopwatchEvents.ValidateRenameName -> {
                val result = validateNameUseCase.validate(item.name)
                setAction(
                    ShowRenameStopwatchDialog(
                        isDialogVisible = true,
                        stopwatchId = _lastDialogStopwatchId,
                        currentName = _lastDialogCurrentName,
                        iconId = _lastDialogIconId,
                        nameError = result.error?.toResource(),
                    )
                )
            }

            is StopwatchEvents.StopwatchDefaultName -> {
                _defaultStopwatchName.tryEmit(item.baseName)
            }
        }
    }
}
