@Composable
fun GradientDialogSurface(
    modifier: Modifier = Modifier,
    shape: Shape = AlertDialogDefaults.shape,
    gradientBrush: Brush? = null,
    content: @Composable () -> Unit,
) {
    val backgroundModifier = if (gradientBrush != null) {
        modifier.background(brush = gradientBrush, shape = shape)
    } else {
        modifier
    }

    val surfaceColor = if (gradientBrush != null) {
        Color.Transparent
    } else {
        MaterialTheme.colorScheme.surface
    }

    val surfaceTonalElevation: Dp = if (gradientBrush != null) 0.dp else AlertDialogDefaults.TonalElevation

    Surface(
        modifier = backgroundModifier,
        shape = shape,
        color = surfaceColor,
        tonalElevation = surfaceTonalElevation,
    ) {
        content()
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun GradientAlertDialog(
    onDismissRequest: () -> Unit,
    content: @Composable (() -> Unit),
    modifier: Modifier = Modifier,
    properties: DialogProperties = DialogProperties(),
    title: String? = null,
    confirmText: String? = null,
    dismissText: String? = null,
    onConfirm: () -> Unit = {},
    onDismissClick: () -> Unit = {},
) {
    val gradientBrush = LocalBackgroundTheme.current.gradientBrush
    BasicAlertDialog(
        onDismissRequest = onDismissRequest,
        modifier = modifier,
        properties = properties,
    ) {
        GradientDialogSurface(gradientBrush = gradientBrush) {
            Column {
                if (title != null) {
                    Spacer(Modifier.height(24.dp))
                    Text(
                        text = title,
                        style = MaterialTheme.typography.headlineSmall,
                        modifier = Modifier.padding(horizontal = 24.dp)
                    )
                    Spacer(Modifier.height(16.dp))
                }

                content()

                if (dismissText != null || confirmText != null) {
                    Spacer(Modifier.height(16.dp))

                    Row(
                        modifier = Modifier.fillMaxWidth().padding(horizontal = 24.dp),
                        horizontalArrangement = Arrangement.End,
                    ) {
                        if (dismissText != null) {
                            TextButton(onClick = onDismissClick) {
                                Text(dismissText)
                            }

                            if (confirmText != null) {
                                Spacer(Modifier.width(8.dp))
                            }
                        }

                        if (confirmText != null) {
                            TextButton(onClick = onConfirm) {
                                Text(confirmText)
                            }
                        }
                    }

                    Spacer(Modifier.height(16.dp))
                }
            }
        }
    }
}
