package com.timemeasurer.app.core.domain.sound

import com.timemeasurer.app.core.domain.settings.VibrationSettingUseCase
import com.timemeasurer.app.core.model.timer.TimerSettingsModel
import com.timemeasurer.app.core.model.timer.TimerTypeModel
import com.timemeasurer.app.core.player.sound.PredefinedSound
import com.timemeasurer.app.core.player.sound.SoundPlayer
import kotlinx.coroutines.flow.first

class PlayTimerPeriodEndSoundUseCase(
    private val soundPlayer: SoundPlayer,
    private val vibrationSettingUseCase: VibrationSettingUseCase,
) {
    suspend operator fun invoke(settings: TimerSettingsModel, type: TimerTypeModel) {
        val (enabled, soundId) = when (type) {
            TimerTypeModel.Session -> settings.isSessionEndSoundEnabled to settings.sessionEndSoundId
            TimerTypeModel.Break, TimerTypeModel.LongBreak -> settings.isRestEndSoundEnabled to settings.restEndSoundId
        }
        if (!enabled || soundId == PredefinedSound.NONE.id) return
        val vibrate = kotlin.runCatching { vibrationSettingUseCase().first() }.getOrDefault(true)
        soundPlayer.play(soundId, vibrate = vibrate)
    }
}
