package com.timemeasurer.app.core.ui.models

import androidx.compose.ui.graphics.vector.ImageVector

/**
 * Immutable description of the top app bar for the current screen.
 *
 * @param title Displayed title. Empty string means no title.
 * @param navigationIcon Icon for the navigation action (e.g. back arrow). Null hides the icon.
 * @param navigationIconContentDescription Accessibility description for the navigation icon.
 * @param actionIcon Icon for the primary action (e.g. settings). Null hides the icon.
 * @param actionIconContentDescription Accessibility description for the action icon.
 * @param onNavigationClick Callback for the navigation icon. Null disables the icon.
 * @param onActionClick Callback for the action icon. Null disables the icon.
 * @param isVisible When false the top bar should not be rendered at all.
 */
data class TopBarState(
    val title: String = "",
    val navigationIcon: ImageVector? = null,
    val navigationIconContentDescription: String? = null,
    val actionIcon: ImageVector? = null,
    val actionIconContentDescription: String? = null,
    val secondActionIcon: ImageVector? = null,
    val secondActionIconContentDescription: String? = null,
    val onNavigationClick: (() -> Unit)? = null,
    val onActionClick: (() -> Unit)? = null,
    val onSecondActionClick: (() -> Unit)? = null,
    val isVisible: Boolean = false,
)
