package com.timemeasurer.app.core.datastore.settings

import com.russhwolf.settings.Settings
import com.timemeasurer.app.core.model.SettingsModel
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.withContext
import kotlinx.serialization.ExperimentalSerializationApi
import kotlinx.serialization.json.Json

@OptIn(ExperimentalSerializationApi::class)
internal class AppSettingsImpl(
    private val settings: Settings,
    private val coroutineDispatcher: CoroutineDispatcher
) : AppSettings {

    private val _settingsFlow = MutableStateFlow<SettingsModel?>(
        settings.getStringOrNull(KEY_SETTINGS)?.let { json ->
            try {
                Json.decodeFromString(SettingsModel.serializer(), json)
            } catch (_: Exception) {
                null
            }
        }
    )

    override suspend fun setSettings(value: SettingsModel) {
        withContext(coroutineDispatcher) {
            settings.putString(KEY_SETTINGS, Json.encodeToString(SettingsModel.serializer(), value))
        }
        _settingsFlow.value = value
    }

    override fun getSettings(): Flow<SettingsModel?> = _settingsFlow.asStateFlow()

    companion object Companion {
        private const val KEY_SETTINGS = "KEY_SETTINGS"
    }
}