package com.timemeasurer.app.feature.timers.widgets

import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.Spacer
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.height
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.layout.size
import androidx.compose.foundation.layout.width
import androidx.compose.foundation.rememberScrollState
import androidx.compose.foundation.verticalScroll
import androidx.compose.runtime.Composable
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import com.timemeasurer.app.core.model.timer.TimerProgressType
import com.timemeasurer.app.feature.timers.models.TimerEvents
import com.timemeasurer.app.feature.timers.models.TimerUiDataModel
import com.timemeasurer.app.feature.timers.models.TimerUiTickModel
import kotlinx.coroutines.flow.StateFlow

private val TIMER_CIRCLE_SIZE = 300.dp
private val TIMER_DISPLAY_MAX_WIDTH = TIMER_CIRCLE_SIZE - 48.dp

@Composable
fun TimerItemContent(
    dataModel: TimerUiDataModel,
    tickState: StateFlow<TimerUiTickModel>,
    onEventAction: (TimerEvents) -> Unit,
    modifier: Modifier = Modifier
) {
    val tick by tickState.collectAsState()

    Box(modifier = modifier.fillMaxSize().verticalScroll(rememberScrollState())) {
        Column(
            modifier = Modifier
                .align(Alignment.Center)
                .then(
                    if (dataModel.progressType == TimerProgressType.Circular)
                        Modifier.padding(16.dp)
                    else
                        Modifier
                ),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            TimerTypeTag(type = dataModel.type)

            Spacer(Modifier.height(8.dp))

            Box(Modifier.width(TIMER_DISPLAY_MAX_WIDTH)) {
                TimerDisplay(time = tick.timer)
            }

            Spacer(Modifier.height(8.dp))

            TimerControls(
                isRunning = dataModel.isRunning,
                onStartPause = { onEventAction(TimerEvents.StartPause(dataModel.timerId)) },
                onReset = { onEventAction(TimerEvents.ShowResetDialog(dataModel.timerId)) },
                onSkip = { onEventAction(TimerEvents.Skip(dataModel.timerId)) },
                onStop = { onEventAction(TimerEvents.Stop(dataModel.timerId)) },
            )
        }

        when (dataModel.progressType) {
            TimerProgressType.Linear -> TimerProgressIndicator(
                progress = tick.progress,
                total = tick.toProgress,
                progressType = TimerProgressType.Linear,
                modifier = Modifier.align(Alignment.BottomCenter),
            )
            TimerProgressType.Circular -> TimerProgressIndicator(
                progress = tick.progress,
                total = tick.toProgress,
                progressType = TimerProgressType.Circular,
                modifier = Modifier.size(TIMER_CIRCLE_SIZE).align(Alignment.Center),
            )
        }
    }
}
