package com.timemeasurer.app.feature.stopwatches_statistics

import androidx.lifecycle.viewModelScope
import com.timemeasurer.app.core.common.di.Inject
import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.domain.stopwatch.GetStopwatchesStatisticsUseCase
import com.timemeasurer.app.core.domain.stopwatch.UpdateStopwatchGraphTypeUseCase
import com.timemeasurer.app.core.ui.ext.toStringResource
import com.timemeasurer.app.core.ui.viewmodels.UiState
import com.timemeasurer.app.core.ui.viewmodels.UiStateViewModel
import com.timemeasurer.app.feature.stopwatches_statistics.models.StopwatchesStatisticsActions
import com.timemeasurer.app.feature.stopwatches_statistics.models.StopwatchesStatisticsEvents
import com.timemeasurer.app.feature.stopwatches_statistics.models.StopwatchesStatisticsUiModel
import com.timemeasurer.app.feature.stopwatches_statistics.models.toStatisticsItem
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.catch
import kotlinx.coroutines.flow.emitAll
import kotlinx.coroutines.flow.flow
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch

class StopwatchesStatisticsViewModel(
    private val getStopwatchesStatisticsUseCase: GetStopwatchesStatisticsUseCase = Inject.instance(),
    private val updateStopwatchGraphTypeUseCase: UpdateStopwatchGraphTypeUseCase = Inject.instance(),
) : UiStateViewModel<StopwatchesStatisticsUiModel, StopwatchesStatisticsActions, StopwatchesStatisticsEvents>(
    initialAction = StopwatchesStatisticsActions.None
) {

    override val state: StateFlow<UiState<StopwatchesStatisticsUiModel>> = flow {
        emitAll(getStopwatchesStatisticsUseCase())
    }.map { result ->
        when (result) {
            is Result.Loading -> UiState.Loading
            is Result.Error -> UiState.Error(result.exception)
            is Result.Success -> {
                val items = result.data.map { it.toStatisticsItem }
                if (items.isEmpty()) UiState.Empty
                else UiState.Success(StopwatchesStatisticsUiModel(items = items))
            }
        }
    }
    .catch { error ->
        println("StopwatchesStatisticsViewModel() - state error: $error")
        setAction(StopwatchesStatisticsActions.ShowError(error.toStringResource))
    }
    .stateIn(
        scope = viewModelScope,
        started = SharingStarted.Lazily,
        initialValue = UiState.Loading
    )

    override fun setEvent(item: StopwatchesStatisticsEvents) {
        when (item) {
            is StopwatchesStatisticsEvents.None -> setAction(StopwatchesStatisticsActions.None)
            is StopwatchesStatisticsEvents.Load -> { /* state is reactive, no action needed */ }
            is StopwatchesStatisticsEvents.UpdateGraphType -> {
                updateGraphType(item.stopwatchId, item.graphType)
            }
        }
    }

    private fun updateGraphType(stopwatchId: Long, graphType: com.timemeasurer.app.core.model.stopwatch.StopwatchGraphType) {
        viewModelScope.launch {
            updateStopwatchGraphTypeUseCase(stopwatchId, graphType)
        }
    }
}
