package com.timemeasurer.app.feature.timer_settings.navigation

import androidx.navigation3.runtime.EntryProviderScope
import androidx.navigation3.runtime.NavKey
import com.timemeasurer.app.core.navigation.AppRoute
import com.timemeasurer.app.core.navigation.AppRouter
import com.timemeasurer.app.feature.timer_settings.TimerSettingsDialog
import com.timemeasurer.app.feature.timer_settings.TimerSettingsScreen

fun EntryProviderScope<NavKey>.timerSettingsEntry(
    appRouter: AppRouter,
) {
    entry<AppRoute.TimerSettings> { key ->
        TimerSettingsScreen(
            timerId = key.timerId,
            onDismiss = { appRouter.goBack() }
        )
    }

    entry<AppRoute.TimerSettingsDialog> { key ->
        TimerSettingsDialog(
            timerId = key.timerId,
            onDismiss = { appRouter.goBack() }
        )
    }
}
