package com.timemeasurer.app.core.data.repositories.timer_session

import app.cash.sqldelight.async.coroutines.awaitAsList
import app.cash.sqldelight.async.coroutines.awaitAsOne
import app.cash.sqldelight.async.coroutines.awaitAsOneOrNull
import app.cash.sqldelight.coroutines.asFlow
import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.common.result.startLoading
import com.timemeasurer.app.core.data.database.AppDatabase
import com.timemeasurer.app.core.data.model.entitiesToTimersSessionsModels
import com.timemeasurer.app.core.data.model.toTimerSessionModel
import com.timemeasurer.app.core.data.model.toTimersSessionsEntity
import com.timemeasurer.app.core.model.converters.dateTimeConverter
import com.timemeasurer.app.core.model.converters.timerTypeConverter
import com.timemeasurer.app.core.model.timer.TimerSessionModel
import com.timemeasurer.app.core.model.timer.TimerTypeModel
import com.timemeasurer.app.core.remote_services.CrashlyticsService
import com.timemeasurer.app.core.remote_services.NoOpCrashlyticsService
import data.TimersSessionsEntity
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.catch
import kotlinx.coroutines.flow.distinctUntilChanged
import kotlinx.coroutines.flow.filterNot
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.flow.onStart
import kotlin.time.Instant
import kotlin.uuid.ExperimentalUuidApi

@OptIn(kotlin.time.ExperimentalTime::class)
internal class TimerSessionRepositoryImpl(
    private val database: AppDatabase,
    private val scope: CoroutineScope,
    private val crashlytics: CrashlyticsService = NoOpCrashlyticsService()
) : TimerSessionRepository {

    override suspend fun getSessionsById(timerId: Long, sinceId: Long, count: Long): Flow<Result<List<TimerSessionModel>>> {
        val dbFlow = database.db().timer_sessionsQueries.selectSinceId(sinceId = sinceId, count = count)
            .asFlow()
            .map { it.awaitAsList() }
            .filterNot { it.isEmpty() }
            .map<List<TimersSessionsEntity>, Result<List<TimerSessionModel>>> {
                Result.Success(it.entitiesToTimersSessionsModels())
            }
            .onStart { emit(Result.Loading) }
            .catch {
                crashlytics.log("TimerRepositoryImpl() - getSessionsById()")
                crashlytics.recordException(it)
                println("TimerRepositoryImpl() - getSessionsById() - error: $it")
                emit(Result.Error(it))
            }

        return dbFlow.startLoading()
            .distinctUntilChanged()
    }

    override suspend fun getSessionByMaxTime(timerId: Long): Flow<Result<TimerSessionModel?>> {
        val dbFlow = database.db().timer_sessionsQueries.selectLastSession(timerId)
            .asFlow()
            .map { it.awaitAsOneOrNull() }
            .map<TimersSessionsEntity?, Result<TimerSessionModel?>> {
                Result.Success(it?.toTimerSessionModel())
            }
            .onStart { emit(Result.Loading) }
            .catch {
                crashlytics.log("TimerRepositoryImpl() - getSessionByMaxTime()")
                crashlytics.recordException(it)
                println("TimerRepositoryImpl() - getSessionByMaxTime(): $it")
                emit(Result.Error(it))
            }

        return dbFlow.startLoading()
            .distinctUntilChanged()
    }

    override suspend fun getSessionByMaxValue(timerId: Long): Flow<Result<List<TimerSessionModel>>> {
        val dbFlow = database.db().timer_sessionsQueries.selectSessionMaxValue(timerId)
            .asFlow()
            .map { it.awaitAsList() }
            .map<List<TimersSessionsEntity>, Result<List<TimerSessionModel>>> {
                Result.Success(it.entitiesToTimersSessionsModels())
            }
            .onStart { emit(Result.Loading) }
            .catch {
                crashlytics.log("TimerRepositoryImpl() - getSessionByMaxValue()")
                crashlytics.recordException(it)
                println("TimerRepositoryImpl() - getSessionByMaxValue() - error: $it")
                emit(Result.Error(it))
            }

        return dbFlow.startLoading()
            .distinctUntilChanged()
    }

    @OptIn(ExperimentalUuidApi::class)
    override suspend fun updateSession(item: TimerSessionModel): Result<TimerSessionModel> {
        val dbResult = runCatching {
            database.db().timer_sessionsQueries.insertOrUpdate(item.toTimersSessionsEntity())
        }
        dbResult.exceptionOrNull()?.let {
            crashlytics.log("TimerRepositoryImpl() - updateSession()")
            crashlytics.recordException(it)
        }

        val result = dbResult.getOrNull() ?: 0L
        println("TimerRepositoryImpl() - updateSession(): ${result}, ${dbResult.exceptionOrNull()}")
        return if (result > 0) Result.Success(item)
                else Result.Error(exception = dbResult.exceptionOrNull(), error = "Rows updated is 0")
    }

    override suspend fun createNewSession(timerId: Long, type: TimerTypeModel, startAt: Instant): Result<TimerSessionModel> {
        val dbResult = runCatching {
            database.db().timer_sessionsQueries.insertNewSessionAndReturn(
                timerId = timerId,
                type = timerTypeConverter(type),
                startedAt = startAt.toEpochMilliseconds(),
                endAt = startAt.toEpochMilliseconds(),
            ).awaitAsOneOrNull()
        }
        dbResult.exceptionOrNull()?.let {
            crashlytics.log("TimerRepositoryImpl() - createNewSession()")
            crashlytics.recordException(it)
        }

        val result = dbResult.getOrNull()
        println("TimerRepositoryImpl() - createNewSession(): ${result}, ${dbResult.exceptionOrNull()}")
        return if (result != null) Result.Success(result.toTimerSessionModel())
            else Result.Error(exception = dbResult.exceptionOrNull(), error = "Create timer fail")
    }

    override suspend fun createExistSession(item: TimerSessionModel): Result<TimerSessionModel> {
        val dbResult = runCatching {
            database.db().timer_sessionsQueries.insertAndReturn(
                timerId = item.timerId,
                session = item.session,
                type = timerTypeConverter(item.type),
                startedAt = dateTimeConverter(item.startedAt),
                endAt = dateTimeConverter(item.endAt)
            ).awaitAsOneOrNull()
        }
        dbResult.exceptionOrNull()?.let {
            crashlytics.log("TimerRepositoryImpl() - createExistSession()")
            crashlytics.recordException(it)
        }

        val result = dbResult.getOrNull()
        println("TimerRepositoryImpl() - createExistSession(): ${result}, ${dbResult.exceptionOrNull()}")
        return if (result != null) Result.Success(result.toTimerSessionModel())
            else Result.Error(exception = dbResult.exceptionOrNull(), error = "Create timer fail")
    }

    override suspend fun getAllSessionsByTimerId(timerId: Long): Flow<Result<List<TimerSessionModel>>> {
        val dbFlow = database.db().timer_sessionsQueries.selectAllByTimerId(timerId)
            .asFlow()
            .map { it.awaitAsList() }
            .map<List<TimersSessionsEntity>, Result<List<TimerSessionModel>>> {
                Result.Success(it.entitiesToTimersSessionsModels())
            }
            .onStart { emit(Result.Loading) }
            .catch {
                crashlytics.log("TimerRepositoryImpl() - getAllSessionsByTimerId()")
                crashlytics.recordException(it)
                println("TimerRepositoryImpl() - getAllSessionsByTimerId() - error: $it")
                emit(Result.Error(it))
            }

        return dbFlow.startLoading()
            .distinctUntilChanged()
    }

    override suspend fun getMaxSession(timerId: Long): Flow<Result<Long>> {
        val dbFlow = database.db().timer_sessionsQueries.maxSession(timerId)
            .asFlow()
            .map { it.awaitAsOne() }
            .map<Long, Result<Long>> { Result.Success(it) }
            .onStart { emit(Result.Loading) }
            .catch {
                crashlytics.log("TimerRepositoryImpl() - getMaxSession()")
                crashlytics.recordException(it)
                println("TimerRepositoryImpl() - getMaxSession() - error: $it")
                emit(Result.Error(it))
            }

        return dbFlow.startLoading()
            .distinctUntilChanged()
    }

    override suspend fun deleteSessions(id: Long): Result<Long> {
        val dbResult = runCatching {
            database.db().timer_sessionsQueries.deleteSessionsById(
                session = id
            )
        }
        dbResult.exceptionOrNull()?.let {
            crashlytics.log("TimerRepositoryImpl() - deleteSessions()")
            crashlytics.recordException(it)
        }

        val result = dbResult.getOrNull()
        println("TimerRepositoryImpl() - deleteSessions(): ${result}, ${dbResult.exceptionOrNull()}")
        return if (result != null) Result.Success(result)
            else Result.Error(exception = dbResult.exceptionOrNull(), error = "Delete sessions fail")
    }

    override suspend fun deleteSessionsByTimerId(timerId: Long): Result<Long> {
        val dbResult = runCatching {
            database.db().timer_sessionsQueries.deleteSessionsByTimerId(timerId = timerId)
        }
        dbResult.exceptionOrNull()?.let {
            crashlytics.log("TimerRepositoryImpl() - deleteSessionsByTimerId()")
            crashlytics.recordException(it)
        }

        val result = dbResult.getOrNull()
        println("TimerRepositoryImpl() - deleteSessionsByTimerId(): ${result}, ${dbResult.exceptionOrNull()}")
        return if (result != null) Result.Success(result)
            else Result.Error(exception = dbResult.exceptionOrNull(), error = "Delete sessions fail")
    }
}