package com.timemeasurer.app.core.remote_services.di

import com.timemeasurer.app.core.remote_services.AnalyticsService
import com.timemeasurer.app.core.remote_services.CrashlyticsService
import com.timemeasurer.app.core.remote_services.NoOpAnalyticsService
import com.timemeasurer.app.core.remote_services.NoOpCrashlyticsService
import com.timemeasurer.app.core.remote_services.NoOpRemoteServicesInitializer
import com.timemeasurer.app.core.remote_services.RemoteServicesInitializer
import org.kodein.di.DI
import org.kodein.di.bind
import org.kodein.di.singleton

actual fun platformRemoteServicesModule(): DI.Module = DI.Module("jsRemoteServicesModule") {
    bind<RemoteServicesInitializer>() with singleton { NoOpRemoteServicesInitializer() }
    bind<CrashlyticsService>() with singleton { NoOpCrashlyticsService() }
    bind<AnalyticsService>() with singleton { NoOpAnalyticsService() }
}
