@Composable
fun ThemesDialog(
    onDismiss: () -> Unit,
    viewModel: ThemesViewModel = viewModel { ThemesViewModel() },
) {
    val state by viewModel.state.collectAsStateWithLifecycle()
    ThemesDialog(
        onDismiss = onDismiss,
        state = state,
        onEvent = viewModel::setEvent,
    )
}

@Composable
fun ThemesDialog(
    onDismiss: () -> Unit,
    state: UiState<ThemesUiModel>,
    onEvent: (ThemesEvents) -> Unit,
) {
    val isDarkTheme = when (state) {
        is UiState.Success -> when (state.item.themeData.darkThemeConfig) {
            DarkThemeConfig.FOLLOW_SYSTEM -> isSystemInDarkTheme()
            DarkThemeConfig.LIGHT -> false
            DarkThemeConfig.DARK -> true
        }
        else -> isSystemInDarkTheme()
    }

    GradientAlertDialog(
        onDismissRequest = onDismiss,
        title = stringResource(Res.string.theme),
        content = {
            Column(
                modifier = Modifier.fillMaxWidth()
                    .verticalScroll(rememberScrollState()),
            ) {
                when (state) {
                    is UiState.Loading -> {
                        Text(
                            text = stringResource(Res.string.theme),
                            modifier = Modifier.padding(horizontal = 24.dp),
                        )
                    }

                    is UiState.Success -> {
                        Spacer(Modifier.height(4.dp))

                        val gradientEnabled = state.item.themeData.isGradientBackgroundEnabled

                        ThemeColorPaletteWidget(
                            selectedColor = state.item.themeData.themeColor,
                            secondarySelectedColor = if (gradientEnabled) state.item.themeData.gradientEndColor else null,
                            columns = 7,
                            swatchSize = 32.dp,
                            onColorSelected = { color ->
                                when (state.item.colorSelectionTarget) {
                                    ColorSelectionTarget.PRIMARY -> onEvent(ThemesEvents.UpdateThemeColor(color))
                                    ColorSelectionTarget.GRADIENT_END -> onEvent(ThemesEvents.UpdateGradientEndColor(color))
                                }
                            },
                            modifier = Modifier.padding(horizontal = 24.dp)
                        )

                        AnimatedVisibility(
                            visible = !isDarkTheme && gradientEnabled,
                            enter = expandVertically() + fadeIn(),
                            exit = shrinkVertically() + fadeOut(),
                        ) {
                            Column(
                                modifier = Modifier.padding(horizontal = 24.dp)
                            ) {
                                Spacer(Modifier.height(16.dp))

                                Text(
                                    text = stringResource(Res.string.theme_color_target),
                                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                                    style = MaterialTheme.typography.bodyLarge,
                                )

                                Spacer(Modifier.height(8.dp))

                                RadioButtonRow(
                                    text = stringResource(Res.string.theme_first_color),
                                    selected = state.item.colorSelectionTarget == ColorSelectionTarget.PRIMARY,
                                    onClick = { onEvent(ThemesEvents.SelectColorTarget(ColorSelectionTarget.PRIMARY)) },
                                    modifier = Modifier.padding(start = 16.dp)
                                )
                                RadioButtonRow(
                                    text = stringResource(Res.string.theme_second_color),
                                    selected = state.item.colorSelectionTarget == ColorSelectionTarget.GRADIENT_END,
                                    onClick = { onEvent(ThemesEvents.SelectColorTarget(ColorSelectionTarget.GRADIENT_END)) },
                                    modifier = Modifier.padding(start = 16.dp)
                                )
                            }
                        }

                        if (!isDarkTheme) {
                            Spacer(Modifier.height(8.dp))
                            TwoLinesSwitchButtonWidget(
                                title = stringResource(Res.string.theme_use_gradient_background),
                                checked = gradientEnabled,
                                onCheckedChange = { onEvent(ThemesEvents.UpdateGradientEnabled(it)) },
                                modifier = Modifier.padding(horizontal = 24.dp, vertical = 4.dp)
                            )
                        }
                    }

                    else -> {
                        Text(
                            text = stringResource(Res.string.theme),
                            modifier = Modifier.padding(vertical = 16.dp, horizontal = 16.dp),
                        )
                    }
                }
            }
        },
        confirmText = stringResource(Res.string.ok),
        onConfirm = onDismiss,
    )
}

