package com.timemeasurer.app.core.ui.widgets

import androidx.compose.foundation.layout.BoxWithConstraints
import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.foundation.layout.width
import androidx.compose.material3.LocalTextStyle
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.text.TextStyle
import androidx.compose.ui.text.font.FontFamily
import androidx.compose.ui.text.rememberTextMeasurer
import androidx.compose.ui.text.style.TextAlign
import androidx.compose.ui.text.style.TextOverflow
import androidx.compose.ui.tooling.preview.Preview
import androidx.compose.ui.unit.TextUnit
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.isSpecified
import androidx.compose.ui.unit.sp

private val DEFAULT_MAX_FONT_SIZE = 57.sp
private const val BINARY_SEARCH_ITERATIONS = 10

@Composable
fun AutoSizeText(
    text: String,
    modifier: Modifier = Modifier,
    style: TextStyle = LocalTextStyle.current,
    color: Color = Color.Unspecified,
    textAlign: TextAlign = TextAlign.Start,
    maxLines: Int = 1,
    minFontSize: TextUnit = 12.sp,
) {
    val textMeasurer = rememberTextMeasurer()

    BoxWithConstraints(modifier = modifier) {
        val maxWidth = constraints.maxWidth.toFloat()
        val maxFontSize = if (style.fontSize.isSpecified) style.fontSize else DEFAULT_MAX_FONT_SIZE

        val computedFontSize = remember(
            text,
            maxWidth,
            style,
            color,
            textAlign,
            maxLines,
            minFontSize,
            maxFontSize,
        ) {
            var low = minFontSize.value
            var high = maxFontSize.value
            var bestFontSize = low

            val baseStyle = style.copy(
                textAlign = textAlign,
                color = if (color != Color.Unspecified) color else style.color,
            )

            for (iteration in 1..BINARY_SEARCH_ITERATIONS) {
                val midVal = (low + high) / 2f
                val candidateStyle = baseStyle.copy(fontSize = midVal.sp)
                val measured = textMeasurer.measure(
                    text = text,
                    style = candidateStyle,
                    maxLines = maxLines,
                    overflow = TextOverflow.Clip,
                )
                if (measured.size.width <= maxWidth) {
                    bestFontSize = midVal
                    low = midVal
                } else {
                    high = midVal
                }
            }
            bestFontSize
        }

        val finalStyle = if (color != Color.Unspecified) {
            style.copy(
                fontSize = computedFontSize.sp,
                color = color,
                textAlign = textAlign,
            )
        } else {
            style.copy(
                fontSize = computedFontSize.sp,
                textAlign = textAlign,
            )
        }

        Text(
            text = text,
            style = finalStyle,
            maxLines = maxLines,
            overflow = TextOverflow.Ellipsis,
            modifier = Modifier.fillMaxWidth()
        )
    }
}

@Preview
@Composable
private fun AutoSizeTextPreview() {
    androidx.compose.material3.MaterialTheme {
        androidx.compose.foundation.layout.Box(
            modifier = Modifier.width(150.dp)
        ) {
            AutoSizeText(
                text = "239:47:11:59",
                style = androidx.compose.material3.MaterialTheme.typography.displayLarge.copy(
                    fontFamily = FontFamily.Monospace
                ),
                textAlign = TextAlign.Center,
            )
        }
    }
}
