package com.timemeasurer.app.feature.splash

import androidx.compose.foundation.background
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.size
import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.getValue
import androidx.compose.runtime.remember
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.unit.dp
import androidx.lifecycle.compose.collectAsStateWithLifecycle
import androidx.lifecycle.viewmodel.compose.viewModel
import com.timemeasurer.app.core.resources.Res
import com.timemeasurer.app.core.resources.oops
import com.timemeasurer.app.core.ui.viewmodels.LocalSnackbarHost
import com.timemeasurer.app.core.ui.viewmodels.UiState
import com.timemeasurer.app.feature.splash.models.SplashActions
import com.timemeasurer.app.feature.splash.models.SplashEvents
import com.timemeasurer.app.widget.cycloid.ProgressWidget
import com.timemeasurer.app.widget.cycloid.ProgressWidgetConfig
import com.timemeasurer.app.widget.cycloid.models.cycloid.CycloidModel
import org.jetbrains.compose.resources.stringResource


@Composable
fun SplashScreen(
    onNavigationEvent: () -> Unit,
    viewModel: SplashViewModel = viewModel { SplashViewModel() }
) {
    println("SplashScreen()")

    val usersUiState by viewModel.state.collectAsStateWithLifecycle()
    val usersAction by viewModel.action.collectAsStateWithLifecycle()

    println("SplashScreen() - state: ${usersUiState.hashCode()}, $usersAction")

    when(val state = usersUiState) {
        is UiState.Success -> {
            val widgetConfig = remember {
                ProgressWidgetConfig(
                    shapeType = CycloidModel.Two(
                        colors = state.item.cycloidColors,
                        lineWidth = 2.dp.value,
                        particleRadius = 10.dp.value
                    ),
                    fromProgress = 0,
                    toProgress = state.item.toProgress
                )
            }

            Box(modifier = Modifier.fillMaxSize().background(Color.White)) {
                ProgressWidget(
                    progress = state.item.progress,
                    widgetConfig = widgetConfig,
                    modifier = Modifier
                        .size(300.dp)
                        .align(Alignment.Center)
                        .clickable {
                            viewModel.setEvent(SplashEvents.OnUserClick)
                        }
                )
            }
        }

        else -> {
            throw IllegalStateException("Wrong states for screen")
        }
    }

    when(val action = usersAction) {
        SplashActions.None -> {}

        is SplashActions.NavigateToUsers -> {
            onNavigationEvent()
            viewModel.setEvent(SplashEvents.None)
        }

        is SplashActions.ShowError -> {
            println("User action: $action")
            val fallbackError = stringResource(Res.string.oops)
            val snackbarHost = LocalSnackbarHost.current
            LaunchedEffect(key1 = action) {
                snackbarHost?.showSnackbar(action.error.message ?: fallbackError)
                viewModel.setEvent(SplashEvents.None)
            }
        }

    }
}

