package com.timemeasurer.app.core.domain.settings

import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.data.repositories.settings.SettingsRepository
import com.timemeasurer.app.core.model.SettingsModel
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.mapNotNull

class KeepScreenOnSettingUseCase(
    private val settingsRepository: SettingsRepository,
) {
    operator fun invoke(): Flow<Boolean> = settingsRepository.getSettings()
        .mapNotNull { result ->
            when (result) {
                is Result.Success -> (result.data ?: SettingsModel()).isKeepScreenOn
                is Result.Error -> SettingsModel().isKeepScreenOn
                is Result.Loading -> null
            }
        }

    suspend fun setEnabled(enabled: Boolean) {
        val current = settingsRepository.getSettings()
            .first { it is Result.Success }
            .let { (it as Result.Success).data ?: SettingsModel() }
        settingsRepository.setSettings(current.copy(isKeepScreenOn = enabled))
    }
}
