package com.timemeasurer.app.core.domain.timer

import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.domain.ext.toHoursMinutes
import com.timemeasurer.app.core.model.timer.TimerModel
import com.timemeasurer.app.core.model.timer.TimerPeriodStatisticsModel
import com.timemeasurer.app.core.model.timer.TimerSessionModel
import com.timemeasurer.app.core.model.timer.TimerStatisticsModel
import com.timemeasurer.app.core.model.timer.TimerTypeModel
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.combine
import kotlinx.coroutines.flow.flatMapLatest
import kotlinx.coroutines.flow.flowOf
import kotlinx.coroutines.flow.flowOn
import kotlinx.coroutines.flow.map
import kotlinx.datetime.LocalDateTime
import kotlinx.datetime.TimeZone
import kotlinx.datetime.toInstant
import kotlinx.datetime.toLocalDateTime
import kotlin.time.Clock
import kotlin.time.Duration.Companion.days
import kotlin.time.ExperimentalTime

@OptIn(ExperimentalTime::class)
class GetTimersStatisticsUseCase(
    private val getTimersUseCase: GetTimersUseCase,
    private val getAllSessionsByTimerIdUseCase: GetAllSessionsByTimerIdUseCase,
    private val dispatcher: CoroutineDispatcher,
) {
    suspend operator fun invoke(): Flow<Result<List<TimerStatisticsModel>>> {
        return getTimersUseCase().flatMapLatest { timersResult ->
            when (timersResult) {
                is Result.Loading -> flowOf(Result.Loading)
                is Result.Error -> flowOf(Result.Error(timersResult.exception, timersResult.error))
                is Result.Success -> {
                    val timers = timersResult.data
                    if (timers.isEmpty()) {
                        return@flatMapLatest flowOf(Result.Success(emptyList()))
                    }

                    val sessionFlows = timers.map { timer ->
                        getAllSessionsByTimerIdUseCase(timer.id).map { sessionsResult ->
                            timer to sessionsResult
                        }
                    }

                    combine(sessionFlows) { timerSessionsArray ->
                        val now = Clock.System.now()
                        val timeZone = TimeZone.currentSystemDefault()
                        val localNow = now.toLocalDateTime(timeZone)
                        val todayStart = LocalDateTime(localNow.year, localNow.month, localNow.day, 0, 0, 0, 0)
                            .toInstant(timeZone)
                            .toEpochMilliseconds()
                        val weekStart = (now - 7.days).toEpochMilliseconds()
                        val monthStart = (now - 30.days).toEpochMilliseconds()

                        val models = timerSessionsArray.mapNotNull { (timer, sessionsResult) ->
                            when (sessionsResult) {
                                is Result.Success -> buildStatisticsModel(
                                    timer,
                                    sessionsResult.data,
                                    todayStart,
                                    weekStart,
                                    monthStart,
                                    timeZone
                                )
                                else -> null
                            }
                        }

                        Result.Success(models)
                    }
                }
            }
        }.flowOn(dispatcher)
    }

    @OptIn(ExperimentalTime::class)
    private fun buildStatisticsModel(
        timer: TimerModel,
        sessions: List<TimerSessionModel>,
        todayStart: Long,
        weekStart: Long,
        monthStart: Long,
        timeZone: TimeZone,
    ): TimerStatisticsModel {
        var todaySession = 0L
        var todayBreak = 0L

        var weekSession = 0L
        var weekBreak = 0L

        var monthSession = 0L
        var monthBreak = 0L

        var totalSession = 0L
        var totalBreak = 0L

        for (session in sessions) {
            val endMillis = session.endAt.toEpochMilliseconds()
            val durationSec = (session.endAt - session.startedAt).inWholeSeconds
            if (durationSec <= 0) continue

            val isToday = endMillis >= todayStart
            val isWeek = endMillis >= weekStart
            val isMonth = endMillis >= monthStart

            when (session.type) {
                TimerTypeModel.Session -> {
                    totalSession += durationSec
                    if (isToday) todaySession += durationSec
                    if (isWeek) weekSession += durationSec
                    if (isMonth) monthSession += durationSec
                }
                TimerTypeModel.Break, TimerTypeModel.LongBreak -> {
                    totalBreak += durationSec
                    if (isToday) todayBreak += durationSec
                    if (isWeek) weekBreak += durationSec
                    if (isMonth) monthBreak += durationSec
                }
            }
        }

        val todayTotal = todaySession + todayBreak
        val todaySessionFraction = if (todayTotal > 0) todaySession.toFloat() / todayTotal else 0f
        val todayPeriodRatio = if (todaySession > 0) todayBreak.toFloat() / todaySession else 0f

        val weekTotal = weekSession + weekBreak
        val weekSessionFraction = if (weekTotal > 0) weekSession.toFloat() / weekTotal else 0f
        val weekPeriodRatio = if (weekSession > 0) weekBreak.toFloat() / weekSession else 0f

        val monthTotal = monthSession + monthBreak
        val monthSessionFraction = if (monthTotal > 0) monthSession.toFloat() / monthTotal else 0f
        val monthPeriodRatio = if (monthSession > 0) monthBreak.toFloat() / monthSession else 0f

        val totalTotal = totalSession + totalBreak
        val totalSessionFraction = if (totalTotal > 0) totalSession.toFloat() / totalTotal else 0f
        val totalPeriodRatio = if (totalSession > 0) totalBreak.toFloat() / totalSession else 0f

        return TimerStatisticsModel(
            timerId = timer.id,
            timerName = timer.name.ifEmpty { "Default" },
            today = TimerPeriodStatisticsModel(
                sessionTime = todaySession.toHoursMinutes(),
                breakTime = todayBreak.toHoursMinutes(),
                sessionFraction = todaySessionFraction,
                periodRatio = todayPeriodRatio,
            ),
            week = TimerPeriodStatisticsModel(
                sessionTime = weekSession.toHoursMinutes(),
                breakTime = weekBreak.toHoursMinutes(),
                sessionFraction = weekSessionFraction,
                periodRatio = weekPeriodRatio,
            ),
            month = TimerPeriodStatisticsModel(
                sessionTime = monthSession.toHoursMinutes(),
                breakTime = monthBreak.toHoursMinutes(),
                sessionFraction = monthSessionFraction,
                periodRatio = monthPeriodRatio,
            ),
            total = TimerPeriodStatisticsModel(
                sessionTime = totalSession.toHoursMinutes(),
                breakTime = totalBreak.toHoursMinutes(),
                sessionFraction = totalSessionFraction,
                periodRatio = totalPeriodRatio,
            ),
        )
    }
}
