package com.timemeasurer.app.feature.timers

import androidx.lifecycle.viewModelScope
import com.timemeasurer.app.core.common.di.Inject
import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.domain.common.NameValidationError
import com.timemeasurer.app.core.domain.common.ValidateNameUseCase
import com.timemeasurer.app.core.domain.timer.TimersInteractors
import com.timemeasurer.app.core.model.icon.DefaultIconIds
import com.timemeasurer.app.core.resources.Res
import com.timemeasurer.app.core.resources.timer_name_empty
import com.timemeasurer.app.core.ui.ext.toStringResource
import com.timemeasurer.app.core.ui.viewmodels.UiState
import com.timemeasurer.app.core.ui.viewmodels.UiStateViewModel
import com.timemeasurer.app.feature.timers.models.DEFAULT_LOADING_TIMER_ID
import com.timemeasurer.app.feature.timers.models.TimerActions
import com.timemeasurer.app.feature.timers.models.TimerEvents
import com.timemeasurer.app.feature.timers.models.TimerUiTickModel
import com.timemeasurer.app.feature.timers.models.TimersUiModel
import com.timemeasurer.app.feature.timers.models.emptyTimersUiModel
import com.timemeasurer.app.feature.timers.models.toTimerUiDataModels
import com.timemeasurer.app.feature.timers.models.toTimerUiTickModel
import kotlinx.coroutines.channels.BufferOverflow
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.catch
import kotlinx.coroutines.flow.combine
import kotlinx.coroutines.flow.distinctUntilChanged
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.flow.stateIn
import kotlin.time.ExperimentalTime


@OptIn(ExperimentalTime::class)
class TimersViewModel(
    private val timersInteractors: TimersInteractors = Inject.instance(),
) : UiStateViewModel<TimersUiModel, TimerActions, TimerEvents>(
    initialAction = TimerActions.None
) {
    private val validateNameUseCase: ValidateNameUseCase = Inject.instance()
    private val _isSpeedDialExpanded = MutableStateFlow(false)
    private val _defaultTimerTickState = MutableStateFlow(TimerUiTickModel())

    private val _defaultTimerName = MutableSharedFlow<String>(replay = 1, onBufferOverflow = BufferOverflow.DROP_LATEST)
    private var _lastDialogTimerId: Long = 0L
    private var _lastDialogIconId: String = DefaultIconIds.TIMER
    private var _lastDialogCurrentName: String = ""

    private fun NameValidationError.toResource() = when (this) {
        NameValidationError.EMPTY -> Res.string.timer_name_empty
    }

    val uiState: StateFlow<UiState<TimersUiModel>> = combine(
        timersInteractors.metadataState,
        _isSpeedDialExpanded,
        _defaultTimerName
    ) { timersState, speedDialState, defaultName ->
        when (timersState) {
            is Result.Error -> UiState.Error(timersState.exception)
            is Result.Loading -> UiState.Success(
                emptyTimersUiModel(defaultName = defaultName, isSpeedDialExpanded = speedDialState)
            )
            is Result.Success -> {
                val timers = timersState.data.toTimerUiDataModels(defaultName = defaultName) {
                    timersInteractors.rename(
                        timerId = it.timerId,
                        name = "$defaultName ${it.timerId}",
                        iconId = it.iconId,
                    )
                }
                if (timers.isEmpty()) {
                    UiState.Success(emptyTimersUiModel(defaultName = defaultName, isSpeedDialExpanded = speedDialState))
                } else {
                    UiState.Success(
                        TimersUiModel(
                            timers = timers,
                            isSpeedDialExpanded = speedDialState,
                            isDeleteVisible = timersState.data.size > 1,
                        )
                    )
                }
            }
        }
    }
    .distinctUntilChanged()
    .catch { error ->
        println("TimersViewModel() - uiState error: $error")
        setAction(TimerActions.ShowError(error.toStringResource))
    }.stateIn(
        scope = viewModelScope,
        started = SharingStarted.Lazily,
        initialValue = UiState.Success(emptyTimersUiModel())
    )

    val tickState: StateFlow<Map<Long, StateFlow<TimerUiTickModel>>> =
        timersInteractors.tickState
            .map { map ->
                map.mapValues { (_, tickFlow) ->
                    tickFlow.map { result ->
                        when (result) {
                            is Result.Success -> result.data.toTimerUiTickModel()
                            else -> TimerUiTickModel()
                        }
                    }.stateIn(
                        scope = viewModelScope,
                        started = SharingStarted.WhileSubscribed(5000),
                        initialValue = TimerUiTickModel()
                    )
                } + (DEFAULT_LOADING_TIMER_ID to _defaultTimerTickState)
            }
            .distinctUntilChanged()
            .stateIn(
                scope = viewModelScope,
                started = SharingStarted.Lazily,
                initialValue = mapOf(DEFAULT_LOADING_TIMER_ID to _defaultTimerTickState)
            )

    override fun setEvent(item: TimerEvents) {
        println("setEvents($item)")
        when (item) {
            is TimerEvents.None -> {
                setAction(TimerActions.None)
                _isSpeedDialExpanded.value = false
            }
            is TimerEvents.ToggleSpeedDial -> _isSpeedDialExpanded.value = !_isSpeedDialExpanded.value
            is TimerEvents.ShowResetDialog -> setAction(
                TimerActions.ShowResetTimerDialog(
                    isDialogVisible = true,
                    timerId = item.timerId,
                )
            )
            is TimerEvents.Reset -> {
                timersInteractors.reset(item.timerId)
                setAction(TimerActions.ShowResetTimerDialog())
                _isSpeedDialExpanded.value = false
            }
            is TimerEvents.StartPause -> timersInteractors.startPause(item.timerId)
            is TimerEvents.Skip -> timersInteractors.skip(item.timerId)
            is TimerEvents.Stop -> timersInteractors.stop(item.timerId)

            is TimerEvents.ShowCreateDialog -> {
                val nextTimerId = (uiState.value as? UiState.Success<TimersUiModel>)?.item?.timers
                    ?.maxOfOrNull { it.timerId }?.plus(1) ?: 1L

                _lastDialogTimerId = nextTimerId
                _lastDialogIconId = DefaultIconIds.TIMER
                setAction(
                    TimerActions.ShowCreateTimerDialog(
                        isDialogVisible = true,
                        timerId = nextTimerId,
                        iconId = DefaultIconIds.TIMER
                    )
                )
            }

            is TimerEvents.Create -> {
                val result = validateNameUseCase.validate(item.name)
                if (!result.isValid) {
                    setAction(
                        TimerActions.ShowCreateTimerDialog(
                            isDialogVisible = true,
                            timerId = _lastDialogTimerId,
                            iconId = item.iconId,
                            nameError = result.error?.toResource(),
                        )
                    )
                } else {
                    timersInteractors.create(item.name, item.iconId)
                    setAction(TimerActions.ShowCreateTimerDialog())
                    _isSpeedDialExpanded.value = false
                }
            }

            is TimerEvents.ShowRenameDialog -> {
                val currentTimer = (uiState.value as? UiState.Success<TimersUiModel>)?.item?.timers
                    ?.getOrNull(item.currentPage) ?: return

                _lastDialogTimerId = currentTimer.timerId
                _lastDialogIconId = currentTimer.iconId
                _lastDialogCurrentName = currentTimer.name
                setAction(
                    TimerActions.ShowRenameTimerDialog(
                        isDialogVisible = true,
                        timerId = currentTimer.timerId,
                        currentName = currentTimer.name,
                        iconId = currentTimer.iconId
                    )
                )
            }

            is TimerEvents.Rename -> {
                val result = validateNameUseCase.validate(item.name)
                if (!result.isValid) {
                    setAction(
                        TimerActions.ShowRenameTimerDialog(
                            isDialogVisible = true,
                            timerId = item.timerId,
                            currentName = item.name,
                            iconId = item.iconId,
                            nameError = result.error?.toResource(),
                        )
                    )
                } else {
                    setAction(TimerActions.None)
                    timersInteractors.rename(item.timerId, item.name, item.iconId)
                    _isSpeedDialExpanded.value = false
                }
            }

            is TimerEvents.ShowDeleteDialog -> {
                val currentTimer = (uiState.value as? UiState.Success<TimersUiModel>)?.item?.timers
                    ?.getOrNull(item.currentPage) ?: return

                setAction(
                    TimerActions.ShowDeleteTimerDialog(
                        isDialogVisible = true,
                        timerId = currentTimer.timerId,
                        currentName = currentTimer.name
                    )
                )
            }

            is TimerEvents.Delete -> {
                timersInteractors.delete(item.timerId)
                setAction(TimerActions.ShowDeleteTimerDialog())
                _isSpeedDialExpanded.value = false
            }

            is TimerEvents.ShowSettings -> {
                val currentTimer = (uiState.value as? UiState.Success<TimersUiModel>)?.item?.timers
                    ?.getOrNull(item.currentPage) ?: return

                setAction(
                    TimerActions.OpenTimerSettings(timerId = currentTimer.timerId)
                )
            }

            is TimerEvents.ShowStatistics -> {
                setAction(TimerActions.OpenStatistics)
            }

            is TimerEvents.OnPageSelected -> {
                val timers = (uiState.value as? UiState.Success<TimersUiModel>)?.item?.timers.orEmpty()
                val activeTimerId = timers.getOrNull(item.page)?.timerId
                timers.forEach { timer ->
                    timersInteractors.setVisible(timer.timerId, timer.timerId == activeTimerId)
                }
            }

            is TimerEvents.ValidateCreateName -> {
                val result = validateNameUseCase.validate(item.name)
                setAction(
                    TimerActions.ShowCreateTimerDialog(
                        isDialogVisible = true,
                        timerId = _lastDialogTimerId,
                        iconId = _lastDialogIconId,
                        nameError = result.error?.toResource(),
                    )
                )
            }

            is TimerEvents.ValidateRenameName -> {
                val result = validateNameUseCase.validate(item.name)
                setAction(
                    TimerActions.ShowRenameTimerDialog(
                        isDialogVisible = true,
                        timerId = _lastDialogTimerId,
                        currentName = _lastDialogCurrentName,
                        iconId = _lastDialogIconId,
                        nameError = result.error?.toResource(),
                    )
                )
            }

            is TimerEvents.TimerDefaultName -> {
                _defaultTimerName.tryEmit(item.baseName)
            }
        }
    }
}
