package com.timemeasurer.app.core.domain.timer

import com.timemeasurer.app.core.common.extensions.roundDown
import com.timemeasurer.app.core.common.extensions.secondsToFormatTimeHMS
import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.common.time.ElapsedTimer
import com.timemeasurer.app.core.common.time.MonotonicClock
import com.timemeasurer.app.core.domain.settings.SingleActiveTimerSettingUseCase
import com.timemeasurer.app.core.domain.sound.TimerSoundInteractor
import com.timemeasurer.app.core.model.ActiveTimerSetting
import com.timemeasurer.app.core.model.timer.TimerMetadataModel
import com.timemeasurer.app.core.model.timer.TimerModel
import com.timemeasurer.app.core.model.timer.TimerSessionModel
import com.timemeasurer.app.core.model.timer.TimerSettingsModel
import com.timemeasurer.app.core.model.timer.TimerTickModel
import com.timemeasurer.app.core.model.timer.TimerTotalSessionsModel
import com.timemeasurer.app.core.model.timer.TimerTypeModel
import com.timemeasurer.app.core.remote_services.CrashlyticsService
import com.timemeasurer.app.core.remote_services.NoOpCrashlyticsService
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Job
import kotlinx.coroutines.currentCoroutineContext
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.catch
import kotlinx.coroutines.flow.combine
import kotlinx.coroutines.flow.distinctUntilChanged
import kotlinx.coroutines.flow.emitAll
import kotlinx.coroutines.flow.filter
import kotlinx.coroutines.flow.flatMapLatest
import kotlinx.coroutines.flow.flow
import kotlinx.coroutines.flow.flowOf
import kotlinx.coroutines.flow.flowOn
import kotlinx.coroutines.flow.onCompletion
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlin.concurrent.atomics.AtomicBoolean
import kotlin.concurrent.atomics.AtomicInt
import kotlin.concurrent.atomics.AtomicLong
import kotlin.concurrent.atomics.ExperimentalAtomicApi
import kotlin.math.min
import kotlin.time.Clock


@OptIn(ExperimentalAtomicApi::class)
class TimerInteractor(
    private val timerModel: TimerModel,
    private val getTimerByIdUseCase: GetTimerByIdUseCase,
    private val getSessionByMaxValueUseCase: GetSessionByMaxValueUseCase,
    private val createNewSessionUseCase: CreateNewSessionUseCase,
    private val createExistSessionUseCase: CreateExistSessionUseCase,
    private val updateSessionUseCase: UpdateSessionUseCase,
    private val deleteSessionsByTimerIdUseCase: DeleteSessionsByTimerIdUseCase,
    private val ioScope: CoroutineScope,
    private val ioDispatcher: CoroutineDispatcher,
    private val clock: MonotonicClock,
    private val timerSoundInteractor: TimerSoundInteractor,
    private val activeTimerSettingUseCase: SingleActiveTimerSettingUseCase,
    private val crashlytics: CrashlyticsService = NoOpCrashlyticsService(),
) {

    companion object {
        private const val MAX_PROGRESS = 100
        private const val MS_PER_SECOND = 1000L
        private const val TIMER_TICK_TIME = 1000L
    }

    private val activeTimerSetting: StateFlow<ActiveTimerSetting> = activeTimerSettingUseCase()
        .stateIn(ioScope, SharingStarted.Eagerly, ActiveTimerSetting())

    private val elapsedTimer = ElapsedTimer(clock)
    private val autoSaveElapsedMs = AtomicLong(0)
    private val pendingSessionResume = AtomicBoolean(false)
    private val sessionCount = AtomicInt(0)
    private val longBreakActive = AtomicBoolean(false)

    private val timerMutex = Mutex()
    private var timerSessionModel: TimerSessionModel? = null
    private var actionJob: Job? = null
    private val periodEndSoundPlayed = AtomicBoolean(false)

    private suspend fun isSessionModelReady(): Boolean = timerMutex.withLock { timerSessionModel != null }

    private fun TimerSessionModel.getSessionTime(settings: TimerSettingsModel): Long = when (type) {
        TimerTypeModel.Session -> settings.sessionDuration
        TimerTypeModel.Break -> settings.shortBreakDuration
        TimerTypeModel.LongBreak -> settings.longBreakDuration
    }

    private fun nextSessionType(current: TimerTypeModel, settings: TimerSettingsModel): TimerTypeModel = when (current) {
        TimerTypeModel.Break, TimerTypeModel.LongBreak -> TimerTypeModel.Session
        TimerTypeModel.Session -> when {
            longBreakActive.load() -> {
                longBreakActive.store(false)
                TimerTypeModel.LongBreak
            }
            settings.isShortBreakEnabled -> TimerTypeModel.Break
            else -> TimerTypeModel.Session
        }
    }

    private fun shouldAutoStart(type: TimerTypeModel, settings: TimerSettingsModel): Boolean = when (type) {
        TimerTypeModel.Session -> settings.isSessionStartAuto
        TimerTypeModel.Break, TimerTypeModel.LongBreak -> settings.isBreakStartAuto
    }

    private fun getProgressTimer(nowTimer: Long, sessionTime: Long) =
        min((maxOf(0L, minOf(nowTimer, sessionTime)).toDouble() / sessionTime * MAX_PROGRESS).toInt(), MAX_PROGRESS)

    private fun getFormattedTimer(nowTimer: Long, sessionTime: Long): String =
        maxOf(0L, (sessionTime - nowTimer) / MS_PER_SECOND).secondsToFormatTimeHMS()

    private suspend fun getRoundedElapseTime(): Long = elapsedTimer.elapsed()
        .roundDown(MS_PER_SECOND)

    private val _timerStateFlow = MutableStateFlow(false)
    private val _isVisibleFlow = MutableStateFlow(true)

    val isVisible: Boolean get() = _isVisibleFlow.value

    val isRunning: Boolean get() = _timerStateFlow.value

    private val _timerTickFlow = _timerStateFlow.flatMapLatest { isRunning ->
        if (isRunning) {
            flow {
                while (currentCoroutineContext().isActive) {
                    emit(true)
                    delay(TIMER_TICK_TIME)
                }
            }
        } else {
            flowOf(false)
        }
    }.flowOn(ioDispatcher)

    private val _timerActionFlow = MutableStateFlow(false)

    private val _currentSessionTypeFlow = MutableStateFlow(TimerTypeModel.Session)

    private val _timerModelFlow = flow {
        emit(Result.Success(timerModel))
        emitAll(getTimerByIdUseCase(timerModel.id))
    }

    val metadataState: StateFlow<Result<TimerMetadataModel>> = combine(
        _timerModelFlow,
        _timerStateFlow,
        _currentSessionTypeFlow,
        activeTimerSetting,
    ) { timerResult, isRunning, sessionType, activeSetting ->
        when (timerResult) {
            is Result.Loading -> Result.Loading
            is Result.Error -> timerResult
            is Result.Success<TimerModel?> -> {
                val timer = timerResult.data ?: return@combine Result.Error(error = "Timer not found")
                val settings = timer.settings

                val canAutoStart = settings.isTimerStartAuto &&
                    (!activeSetting.isEnabled || activeSetting.activeTimerId == timerModel.id)

                if (canAutoStart && !isSessionModelReady() && !isRunning) {
                    elapsedTimer.start()
                    _timerStateFlow.value = true
                }

                Result.Success(
                    TimerMetadataModel(
                        timerId = timerModel.id,
                        name = timer.name,
                        iconId = settings.iconId,
                        isRunning = _timerStateFlow.value,
                        type = sessionType,
                        progressType = settings.progressType,
                    )
                )
            }
        }
    }
    .onCompletion {
        println("TimerInteractor(${timerModel.id}) - metadataState - onCompletion(): $it")
    }
    .catch {
        crashlytics.log("TimerInteractor(${timerModel.id}) - metadataState")
        crashlytics.recordException(it)
        println("TimerInteractor(${timerModel.id}) - metadataState - catch(): $it")
        emit(Result.Error(it))
    }
    .distinctUntilChanged()
    .flowOn(ioDispatcher)
    .stateIn(
        scope = ioScope,
        started = SharingStarted.Lazily,
        initialValue = Result.Loading
    )

    val tickState: StateFlow<Result<TimerTickModel>> = combine(
        _timerTickFlow,
        _timerActionFlow,
        _timerModelFlow,
        _isVisibleFlow,
    ) { timerTick, timerAction, timer, isVisible ->
        println("TimerInteractor(${timerModel.id}) - tickState: $timerTick, ${getRoundedElapseTime()}")

        val settings = when (timer) {
            is Result.Loading -> return@combine Result.Loading
            is Result.Error -> return@combine Result.Error(timer.exception, timer.error)
            is Result.Success<TimerModel?> -> timer.data?.settings ?: TimerSettingsModel()
        }

        var session = when (val result = getSessionModel(timerTick)) {
            is Result.Loading -> return@combine Result.Loading
            is Result.Error -> return@combine Result.Error(result.exception, result.error)
            is Result.Success<TimerSessionModel> -> result.data
        }

        var sessionTimeSettings = session.getSessionTime(settings)
        var nowTimer = getRoundedElapseTime()
        var progress = getProgressTimer(nowTimer, sessionTimeSettings)
        var formattedTime = getFormattedTimer(nowTimer, sessionTimeSettings)
        val sessionTimeNext = sessionTimeSettings + MS_PER_SECOND

        // Countdown beeps (last 3 seconds)
        if (timerTick && nowTimer < sessionTimeSettings) {
            val remainingMs = sessionTimeSettings - nowTimer
            if (remainingMs in 1..3000) {
                if (isVisible) timerSoundInteractor.playCountdown(settings)
            }
        }

        // Period-end sound at 00:00, BEFORE creating next session
        if (timerTick && nowTimer >= sessionTimeSettings && !periodEndSoundPlayed.load()) {
            periodEndSoundPlayed.store(true)
            if (isVisible) timerSoundInteractor.playPeriodEnd(settings, session.type)
        }

        when (val result = getNextSession(timerTick, nowTimer, sessionTimeNext, session, settings)) {
            is Result.Loading -> return@combine Result.Loading
            is Result.Error -> return@combine Result.Error(result.exception, result.error)
            is Result.Success<TimerSessionModel> -> result.data.also {
                periodEndSoundPlayed.store(false)
                session = it
                sessionTimeSettings = it.getSessionTime(settings)
                nowTimer = getRoundedElapseTime()
                progress = getProgressTimer(nowTimer, sessionTimeSettings)
                formattedTime = getFormattedTimer(nowTimer, sessionTimeSettings)
                if (!shouldAutoStart(session.type, settings)) {
                    _timerStateFlow.value = false
                    elapsedTimer.pause()
                }
            }
            else -> println("TimerInteractor(${timerModel.id}) - new next type: none")
        }

        saveSession(timerTick, session, settings, nowTimer)

        _currentSessionTypeFlow.value = session.type

        Result.Success(
            TimerTickModel(
                timerId = timerModel.id,
                timer = formattedTime,
                progress = progress,
                toProgress = MAX_PROGRESS,
                isVisible = isVisible
            )
        )
    }
    .filter { _isVisibleFlow.value }
    .distinctUntilChanged()
    .catch {
        crashlytics.log("TimerInteractor(${timerModel.id}) - tickState")
        crashlytics.recordException(it)
        println("TimerInteractor(${timerModel.id}) - tickState - catch(): $it")
        emit(Result.Error(it))
    }
    .stateIn(
        scope = ioScope,
        started = SharingStarted.Lazily,
        initialValue = Result.Loading
    )

    private suspend fun getNextSession(
        timerTick: Boolean,
        nowTimer: Long,
        sessionTime: Long,
        session: TimerSessionModel,
        settings: TimerSettingsModel,
    ): Result<TimerSessionModel>? {
        if (!timerTick || nowTimer < sessionTime) return null
        tryActivateLongBreak(settings, session.type)
        return updateAndCreateNextSession(session, settings)
    }

    private fun tryActivateLongBreak(settings: TimerSettingsModel, type: TimerTypeModel) {
        if (!settings.isLongBreakEnabled || type != TimerTypeModel.Session) return
        if (sessionCount.addAndFetch(1) % settings.longBreakAfterSession == 0) {
            sessionCount.store(0)
            longBreakActive.store(true)
        }
    }

    private fun saveSession(
        timerTick: Boolean,
        session: TimerSessionModel,
        settings: TimerSettingsModel,
        nowTimer: Long,
    ) {
        if (!timerTick) return

        val periodMs = settings.autoSaveSession * MS_PER_SECOND
        if (periodMs <= 0) return

        val currentPeriod = nowTimer / periodMs
        val lastPeriod = autoSaveElapsedMs.load() / periodMs
        if (currentPeriod <= lastPeriod) return

        autoSaveElapsedMs.store(nowTimer)

        ioScope.launch {
            updateSessionUseCase(session.copy(endAt = Clock.System.now()))
        }
    }

    private suspend fun getSessionModel(timerTick: Boolean): Result<TimerSessionModel> =
        timerMutex.withLock {
            val model = timerSessionModel
            when {
                model != null && timerTick -> handleResumingSession(model)
                model != null -> handlePausingSession(model)
                else -> initializeSession()
            }.also { if (it is Result.Success) timerSessionModel = it.data }
        }

    private suspend fun handleResumingSession(model: TimerSessionModel): Result<TimerSessionModel> {
        if (!pendingSessionResume.exchange(false)) return Result.Success(model)
        val now = Clock.System.now()
        return createExistSessionUseCase(model.copy(startedAt = now, endAt = now))
    }

    private suspend fun handlePausingSession(model: TimerSessionModel): Result<TimerSessionModel> {
        pendingSessionResume.store(true)
        return updateSessionUseCase(model.copy(endAt = Clock.System.now()))
    }

    private suspend fun initializeSession(): Result<TimerSessionModel> {
        when (val result = getSessionByMaxValueUseCase(timerModel.id)) {
            is Result.Loading, is Result.Error -> return result
            is Result.Success<TimerTotalSessionsModel?>? -> result.data?.let { totals ->
                val recoveredMs = totals.timeSec * MS_PER_SECOND
                elapsedTimer.add(recoveredMs)
                autoSaveElapsedMs.store(recoveredMs)
                val now = Clock.System.now()
                return createExistSessionUseCase(totals.session.copy(startedAt = now, endAt = now))
            }
        }

        return createNewSessionUseCase(timerId = timerModel.id, type = TimerTypeModel.Session)
    }

    private suspend fun updateAndCreateNewSession(
        itemForSave: TimerSessionModel? = null,
        modifyForNew: ((TimerSessionModel) -> TimerSessionModel)? = null,
    ): Result<TimerSessionModel> =
        timerMutex.withLock {
            val saveModel = (itemForSave ?: timerSessionModel)
                ?: return@withLock Result.Error(error = "Timer model state is null")

            when (val result = updateSessionUseCase(saveModel.copy(endAt = Clock.System.now()))) {
                is Result.Error, is Result.Loading -> return@withLock result
                is Result.Success<TimerSessionModel> -> {}
            }

            val newModel = modifyForNew?.invoke(saveModel) ?: saveModel
            when (val result = createNewSessionUseCase(
                timerId = newModel.timerId,
                type = newModel.type,
            )) {
                is Result.Error, is Result.Loading -> result
                is Result.Success<TimerSessionModel> -> result.also {
                    resetElapsed(running = _timerStateFlow.value)
                    timerSessionModel = it.data
                }
            }
        }

    private suspend fun updateAndCreateNextSession(
        item: TimerSessionModel? = null,
        settings: TimerSettingsModel,
    ): Result<TimerSessionModel> =
        updateAndCreateNewSession(
            itemForSave = item,
            modifyForNew = { it.copy(type = nextSessionType(it.type, settings)) },
        )

    private suspend fun resetElapsed(running: Boolean = false) {
        autoSaveElapsedMs.store(0)
        elapsedTimer.reset()
        periodEndSoundPlayed.store(false)
        if (running) elapsedTimer.start()
    }

    private fun launchAction(block: suspend () -> Unit) {
        if (actionJob?.isActive == true) return
        actionJob = ioScope.launch { block() }
    }

    suspend fun startPause() {
        if (_timerStateFlow.value) elapsedTimer.pause() else elapsedTimer.start()
        _timerStateFlow.update { !it }
    }

    fun skip() = launchAction {
        updateAndCreateNextSession(settings = timerModel.settings)
            .takeIf { it is Result.Success }
            ?.let { _timerActionFlow.update { !it } }
    }

    fun reset() = launchAction {
        timerMutex.withLock {
            val wasRunning = _timerStateFlow.value

            when (val result = deleteSessionsByTimerIdUseCase(timerModel.id)) {
                is Result.Error, is Result.Loading -> return@withLock
                is Result.Success<Long> -> {
                    timerSessionModel = null
                    pendingSessionResume.store(false)
                    sessionCount.store(0)
                    longBreakActive.store(false)
                    resetElapsed(running = wasRunning)
                }
            }

            _timerActionFlow.update { !it }
        }
    }

    fun stop() = launchAction {
        updateAndCreateNewSession()
            .takeIf { it is Result.Success }
            ?.let { _timerStateFlow.update { false } }
    }

    fun setVisible(isVisible: Boolean) {
        _isVisibleFlow.value = isVisible
    }
}
