@Composable
fun StopwatchesScreen(
    onStatisticsClick: () -> Unit = {},
    onStopwatchSelected: () -> Unit = {},
    isExpanded: Boolean = false,
    viewModel: StopwatchesViewModel = viewModel { StopwatchesViewModel() },
    topBarNavigationViewModel: TopBarNavigationViewModel = viewModel { TopBarNavigationViewModel() },
) {
    println("StopwatchesScreen()")

    val uiState by viewModel.uiState.collectAsStateWithLifecycle()
    val tickState by viewModel.tickState.collectAsStateWithLifecycle()
    val action by viewModel.action.collectAsStateWithLifecycle()

    println("StopwatchesScreen() - state: $uiState, $action")

    val defaultStopwatchName = stringResource(Res.string.stopwatch)
    LaunchedEffect(Unit) {
        viewModel.setEvent(StopwatchEvents.StopwatchDefaultName(defaultStopwatchName))
    }

    LaunchedEffect(Unit) {
        topBarNavigationViewModel.collect("stopwatches").collect { event ->
            when (event) {
                TopBarNavigationState.Statistics -> {
                    onStatisticsClick()
                    topBarNavigationViewModel.emit("stopwatches", TopBarNavigationState.None)
                }
                else -> {}
            }
        }
    }

    when (val state = uiState) {
        UiState.Empty -> SimplePlaceholderContent(
            header = stringResource(Res.string.empty),
            title = stringResource(Res.string.no_data_to_display),
            image = MainIconSet.search.icon,
            imageContentDescription = stringResource(Res.string.no_data_to_display)
        )

        is UiState.Success -> {
            if (state.item.stopwatches.isEmpty()) {
                Box(modifier = Modifier.fillMaxSize()) {
                    SimplePlaceholderContent(
                        header = stringResource(Res.string.empty),
                        title = stringResource(Res.string.no_data_to_display),
                        image = MainIconSet.search.icon,
                        imageContentDescription = stringResource(Res.string.no_data_to_display)
                    )
                    if (state.item.isSpeedDialExpanded) {
                        Box(
                            modifier = Modifier
                                .fillMaxSize()
                                .clickable(
                                    interactionSource = remember { MutableInteractionSource() },
                                    indication = null
                                ) {
                                    viewModel.setEvent(StopwatchEvents.ToggleSpeedDial)
                                }
                        )
                    }
                    StopwatchSpeedDial(
                        isExpanded = state.item.isSpeedDialExpanded,
                        showDelete = state.item.isDeleteVisible,
                        onToggle = { viewModel.setEvent(StopwatchEvents.ToggleSpeedDial) },
                        onCreate = { viewModel.setEvent(StopwatchEvents.ShowCreateDialog) },
                        onRename = {},
                        onDelete = {},
                        modifier = Modifier
                            .align(if (isExpanded) Alignment.BottomStart else Alignment.BottomEnd)
                            .padding(
                                start = if (isExpanded) 16.dp else 0.dp,
                                end = if (isExpanded) 0.dp else 16.dp,
                                bottom = 16.dp
                            )
                    )
                }
            } else {
                val stopwatches = state.item.stopwatches
                val pagerState = rememberPagerState(pageCount = { stopwatches.size })
                val lastIndex = stopwatches.lastIndex
                val selectedTabIndex = pagerState.currentPage.coerceIn(0, lastIndex)

                LaunchedEffect(stopwatches.size) {
                    if (pagerState.currentPage > lastIndex) {
                        pagerState.scrollToPage(lastIndex)
                    }
                }

                LaunchedEffect(pagerState) {
                    snapshotFlow { pagerState.currentPage }.collect { page ->
                        println("StopwatchesScreen() - onPageChange: $page")
                        viewModel.setEvent(StopwatchEvents.OnPageSelected(page))
                        if (isExpanded) {
                            onStopwatchSelected()
                        }
                    }
                }

                val coroutineScope = rememberCoroutineScope()

                val tabItems = stopwatches.map { stopwatch ->
                    AnimatedTabItem(
                        title = stopwatch.name.takeIf { it.isNotEmpty() }
                            ?: stringResource(Res.string.default),
                        icon = AppIconRegistry.findById(stopwatch.iconId)?.icon,
                    )
                }

                Box(modifier = Modifier.fillMaxSize()) {
                    Column(modifier = Modifier.fillMaxSize()) {
                        AnimatedTabRowWidget(
                            items = tabItems,
                            selectedPage = pagerState.currentPage,
                            pageOffset = pagerState.currentPageOffsetFraction,
                            onTabClick = { index ->
                                coroutineScope.launch {
                                    pagerState.animateScrollToPage(index)
                                }
                            },
                            modifier = Modifier.fillMaxWidth(),
                        )

                        HorizontalPager(
                            state = pagerState,
                            pageSize = PageSize.Fill,
                            pageSpacing = 16.dp,
                            contentPadding = PaddingValues(all = 0.dp),
                            beyondViewportPageCount = 1,
                            modifier = Modifier.fillMaxSize()
                        ) { page ->
                            val stopwatchData = stopwatches[page]
                            println("StopwatchesScreen() - HorizontalPager: $page, ${stopwatchData.stopwatchId}")
                            val stopwatchTickState = tickState[stopwatchData.stopwatchId] ?: return@HorizontalPager
                            StopwatchItemContent(
                                dataModel = stopwatchData,
                                tickState = stopwatchTickState,
                                onEventAction = viewModel::setEvent,
                                modifier = Modifier.fillMaxSize()
                            )
                        }
                    }

                    if (state.item.isSpeedDialExpanded) {
                        Box(
                            modifier = Modifier
                                .fillMaxSize()
                                .clickable(
                                    interactionSource = remember { MutableInteractionSource() },
                                    indication = null
                                ) {
                                    viewModel.setEvent(StopwatchEvents.ToggleSpeedDial)
                                }
                        )
                    }

                    StopwatchSpeedDial(
                        isExpanded = state.item.isSpeedDialExpanded,
                        showDelete = state.item.isDeleteVisible,
                        onToggle = { viewModel.setEvent(StopwatchEvents.ToggleSpeedDial) },
                        onCreate = { viewModel.setEvent(StopwatchEvents.ShowCreateDialog) },
                        onRename = { viewModel.setEvent(StopwatchEvents.ShowRenameDialog(selectedTabIndex)) },
                        onDelete = { viewModel.setEvent(StopwatchEvents.ShowDeleteDialog(selectedTabIndex)) },
                        modifier = Modifier
                            .align(if (isExpanded) Alignment.BottomStart else Alignment.BottomEnd)
                            .padding(
                                start = if (isExpanded) 16.dp else 0.dp,
                                end = if (isExpanded) 0.dp else 16.dp,
                                bottom = 16.dp
                            )
                    )

                    if (state.item.isLoading) {
                        Box(
                            modifier = Modifier
                                .fillMaxSize()
                                .clickable(
                                    interactionSource = remember { MutableInteractionSource() },
                                    indication = null,
                                    onClick = {}
                                )
                        )
                    }
                }
            }
        }

        is UiState.Error -> {
            Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                Text(
                    text = state.throwable?.message ?: stringResource(Res.string.unknown_error)
                )
            }
        }

        else -> {}
    }

    when (val action = action) {
        StopwatchActions.None -> {}

        is StopwatchActions.ShowError -> {
            println("User action: $action")
            val error = stringResource(action.error)
            val snackbarHost = LocalSnackbarHost.current
            LaunchedEffect(key1 = action) {
                snackbarHost?.showSnackbar(error)
                viewModel.setEvent(StopwatchEvents.None)
            }
        }

        is StopwatchActions.ShowCreateStopwatchDialog -> {
            if (action.isDialogVisible) {
                IconPickerInputDialog(
                    title = stringResource(Res.string.input_timer_name),
                    initialText = stringResource(Res.string.stopwatch_default_name_format, action.stopwatchId.toInt()),
                    initialIconId = action.iconId,
                    confirmText = stringResource(Res.string.create),
                    onConfirm = { name, iconId -> viewModel.setEvent(StopwatchEvents.Create(name, iconId)) },
                    onDismiss = { viewModel.setEvent(StopwatchEvents.None) },
                    nameError = action.nameError,
                    onValidateName = { name -> viewModel.setEvent(StopwatchEvents.ValidateCreateName(name)) },
                    maxNameLength = action.maxNameLength,
                )
            }
        }

        is StopwatchActions.ShowRenameStopwatchDialog -> {
            if (action.isDialogVisible) {
                IconPickerInputDialog(
                    title = stringResource(Res.string.input_timer_rename),
                    initialText = action.currentName,
                    initialIconId = action.iconId,
                    confirmText = stringResource(Res.string.save),
                    onConfirm = { name, iconId -> viewModel.setEvent(StopwatchEvents.Rename(action.stopwatchId, name, iconId)) },
                    onDismiss = { viewModel.setEvent(StopwatchEvents.None) },
                    nameError = action.nameError,
                    onValidateName = { name -> viewModel.setEvent(StopwatchEvents.ValidateRenameName(name)) },
                    maxNameLength = action.maxNameLength,
                )
            }
        }

        is StopwatchActions.ShowDeleteStopwatchDialog -> {
            if (action.isDialogVisible) {
                SimpleDialog(
                    dialogTitle = stringResource(Res.string.delete_stopwatch),
                    dialogText = stringResource(Res.string.confirm_delete_stopwatch),
                    confirmText = stringResource(Res.string.delete),
                    onConfirmation = { viewModel.setEvent(StopwatchEvents.Delete(action.stopwatchId)) },
                    onCancel = { viewModel.setEvent(StopwatchEvents.None) },
                    dismissText = stringResource(Res.string.close),
                )
            }
        }

        is StopwatchActions.ShowResetStopwatchDialog -> {
            if (action.isDialogVisible) {
                SimpleDialog(
                    dialogTitle = stringResource(Res.string.stopwatch_reset_title),
                    dialogText = stringResource(Res.string.stopwatch_reset_message),
                    confirmText = stringResource(Res.string.stopwatch_reset),
                    dismissText = stringResource(Res.string.cancel),
                    onConfirmation = { viewModel.setEvent(StopwatchEvents.ConfirmReset(action.stopwatchId)) },
                    onCancel = { viewModel.setEvent(StopwatchEvents.None) },
                )
            }
        }

        is StopwatchActions.OpenStatistics -> {
            LaunchedEffect(key1 = action) {
                onStatisticsClick()
                viewModel.setEvent(StopwatchEvents.None)
            }
        }
    }
}
