package com.timemeasurer.app.core.data.repositories.settings

import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.common.result.startLoading
import com.timemeasurer.app.core.datastore.settings.AppSettings
import com.timemeasurer.app.core.model.SettingsModel
import com.timemeasurer.app.core.remote_services.CrashlyticsService
import com.timemeasurer.app.core.remote_services.NoOpCrashlyticsService
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.catch
import kotlinx.coroutines.flow.map

internal class SettingsRepositoryImpl(
    private val appSettings: AppSettings,
    private val crashlytics: CrashlyticsService = NoOpCrashlyticsService()
) : SettingsRepository {

    override suspend fun setSettings(value: SettingsModel) = appSettings.setSettings(value)

    override fun getSettings(): Flow<Result<SettingsModel?>> = appSettings.getSettings()
        .map<SettingsModel?, Result<SettingsModel?>> { Result.Success(it) }
        .catch {
            crashlytics.log("SettingsRepositoryImpl() - getSettings()")
            crashlytics.recordException(it)
            println("SettingsRepositoryImpl() - getSettings(): $it")
            emit(Result.Error(it))
        }.startLoading()

}
