package com.timemeasurer.app.core.domain.timer

import com.timemeasurer.app.core.model.timer.TimerTimeType

class ValidateTimerDurationUseCase {

    companion object {
        const val MAX_MS = 24L * 60 * 60 * 1000 // 24 hours in ms
    }

    private fun minMs(unit: TimerTimeType): Long = when (unit) {
        TimerTimeType.HOURS -> 1L * 60 * 60 * 1000
        TimerTimeType.MINUTES -> 1L * 60 * 1000
        TimerTimeType.SECONDS -> 5L * 1000
    }

    private fun displayBounds(unit: TimerTimeType): Pair<Int, Int> = when (unit) {
        TimerTimeType.HOURS -> 1 to 24
        TimerTimeType.MINUTES -> 1 to 1440
        TimerTimeType.SECONDS -> 5 to 86400
    }

    fun validate(ms: Long, unit: TimerTimeType): ValidateTimerDurationResult {
        val min = minMs(unit)
        val validatedMs = ms.coerceIn(min, MAX_MS)
        val (displayMin, displayMax) = displayBounds(unit)
        return ValidateTimerDurationResult(
            validatedMs = validatedMs,
            isClamped = validatedMs != ms,
            displayMin = displayMin,
            displayMax = displayMax,
        )
    }

    fun convertAndValidate(currentMs: Long, newUnit: TimerTimeType): ValidateTimerDurationResult {
        val convertedMs = (currentMs / newUnit.factorToMs) * newUnit.factorToMs
        return validate(convertedMs, newUnit)
    }
}
