data class AnimatedTabItem(
    val title: String,
    val icon: ImageVector? = null,
)

@Composable
fun AnimatedTabRowWidget(
    items: List<AnimatedTabItem>,
    selectedPage: Int,
    pageOffset: Float,
    onTabClick: (Int) -> Unit,
    modifier: Modifier = Modifier,
    shape: RoundedCornerShape = RoundedCornerShape(16.dp),
    activeBackgroundColor: Color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.7f),
    borderColor: Color = MaterialTheme.colorScheme.outline,
    borderWidth: Dp = 1.dp,
    tabSpacing: Dp = 8.dp,
    tabPadding: PaddingValues = PaddingValues(horizontal = 12.dp, vertical = 6.dp),
    iconSize: Dp = 20.dp,
    containerPadding: Dp = 16.dp,
    tabBackgroundColor: Color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.2f),
) {
    val selectedPageState = rememberUpdatedState(selectedPage)
    val pageOffsetState = rememberUpdatedState(pageOffset)
    val scrollState = rememberScrollState()

    val tabPositionsState = remember { mutableStateOf<List<TabPositionData>>(emptyList()) }
    var viewportWidth by remember { mutableStateOf(0) }
    val containerPaddingPx = with(LocalDensity.current) { containerPadding.roundToPx() }

    LaunchedEffect(selectedPage, viewportWidth, containerPaddingPx, tabPositionsState.value) {
        val positions = tabPositionsState.value
        if (positions.isEmpty() || viewportWidth <= 0) return@LaunchedEffect
        val activeTab = positions.getOrNull(selectedPage) ?: return@LaunchedEffect
        val visibleWidth = (viewportWidth - 2 * containerPaddingPx).coerceAtLeast(0)
        val target = (activeTab.left + activeTab.width / 2 - visibleWidth / 2)
            .coerceIn(0, scrollState.maxValue)
        scrollState.animateScrollTo(target)
    }

    Box(
        modifier = modifier
            .horizontalScroll(scrollState)
            .onGloballyPositioned { viewportWidth = it.size.width },
    ) {
        Layout(
            modifier = Modifier
                .padding(horizontal = containerPadding)
                .drawBehind {
                    val sel = selectedPageState.value
                    val offset = pageOffsetState.value

                    val currentPositions = tabPositionsState.value
                    if (currentPositions.isEmpty()) return@drawBehind

                    val cornerRadiusPx = shape.topStart.toPx(size, this)
                    val borderWidthPx = borderWidth.toPx()

                    currentPositions.forEach { tab ->
                        drawRoundRect(
                            color = tabBackgroundColor,
                            topLeft = Offset(tab.left.toFloat(), tab.top.toFloat()),
                            size = Size(tab.width.toFloat(), tab.height.toFloat()),
                            cornerRadius = CornerRadius(cornerRadiusPx, cornerRadiusPx),
                        )
                    }

                    val lastIndex = (items.size - 1).coerceAtLeast(0)
                    val fractionalIndex = (sel + offset).coerceIn(0f, lastIndex.toFloat())
                    val fromIndex = fractionalIndex.toInt().coerceAtMost(lastIndex)
                    val toIndex = (fromIndex + 1).coerceAtMost(lastIndex)
                    val progress = fractionalIndex - fromIndex

                    val fromTab = currentPositions[fromIndex]
                    val toTab = currentPositions[toIndex]

                    val top = lerp(fromTab.top.toFloat(), toTab.top.toFloat(), progress)
                    val height = lerp(fromTab.height.toFloat(), toTab.height.toFloat(), progress)

                    val startLeft = fromTab.left.toFloat()
                    val startRight = startLeft + fromTab.width.toFloat()
                    val endLeft = toTab.left.toFloat()
                    val endRight = endLeft + toTab.width.toFloat()

                    val coverageLeft = min(startLeft, endLeft)
                    val coverageRight = max(startRight, endRight)

                    val wormLeft: Float
                    val wormRight: Float
                    if (progress <= 0.5f) {
                        val phaseProgress = progress * 2f
                        wormLeft = lerp(startLeft, coverageLeft, phaseProgress)
                        wormRight = lerp(startRight, coverageRight, phaseProgress)
                    } else {
                        val phaseProgress = (progress - 0.5f) * 2f
                        wormLeft = lerp(coverageLeft, endLeft, phaseProgress)
                        wormRight = lerp(coverageRight, endRight, phaseProgress)
                    }

                    val left = wormLeft
                    val width = wormRight - wormLeft

                    drawRoundRect(
                        color = activeBackgroundColor,
                        topLeft = Offset(left, top),
                        size = Size(width, height),
                        cornerRadius = CornerRadius(cornerRadiusPx, cornerRadiusPx),
                    )

                    val halfBorder = borderWidthPx / 2f
                    drawRoundRect(
                        color = borderColor,
                        topLeft = Offset(left + halfBorder, top + halfBorder),
                        size = Size(width - borderWidthPx, height - borderWidthPx),
                        cornerRadius = CornerRadius(cornerRadiusPx - halfBorder, cornerRadiusPx - halfBorder),
                        style = Stroke(width = borderWidthPx),
                    )
                },
            content = {
                items.forEachIndexed { index, item ->
                    TabContent(
                        item = item,
                        onClick = { onTabClick(index) },
                        tabPadding = tabPadding,
                        iconSize = iconSize,
                        shape = shape,
                    )
                }
            }
        ) { measurables, constraints ->
            val tabSpacingPx = tabSpacing.roundToPx()
            val placeables = measurables.map { it.measure(constraints) }

            val positions = mutableListOf<TabPositionData>()
            var x = 0
            var maxHeight = 0

            placeables.forEach { placeable ->
                positions.add(
                    TabPositionData(
                        left = x,
                        top = 0,
                        width = placeable.width,
                        height = placeable.height,
                    )
                )
                x += placeable.width + tabSpacingPx
                if (placeable.height > maxHeight) maxHeight = placeable.height
            }

            val totalWidth = if (positions.isNotEmpty()) x - tabSpacingPx else 0

            val positionList = positions.toList()
            if (positionList != tabPositionsState.value) {
                tabPositionsState.value = positionList
            }

            layout(totalWidth.coerceAtLeast(0), maxHeight) {
                placeables.forEachIndexed { index, placeable ->
                    placeable.placeRelative(positions[index].left, positions[index].top)
                }
            }
        }
    }
}

@Composable
private fun TabContent(
    item: AnimatedTabItem,
    onClick: () -> Unit,
    tabPadding: PaddingValues,
    iconSize: Dp,
    shape: RoundedCornerShape,
) {
    Column(
        modifier = Modifier
            .heightIn(min = 48.dp)
            .clip(shape)
            .clickable(onClick = onClick)
            .padding(tabPadding),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.Center,
    ) {
        if (item.icon != null) {
            Icon(
                imageVector = item.icon,
                contentDescription = item.title,
                modifier = Modifier.size(iconSize),
            )
        }
        Text(
            text = item.title,
            fontSize = 14.sp,
        )
    }
}

private data class TabPositionData(
    val left: Int,
    val top: Int,
    val width: Int,
    val height: Int,
)

private fun lerp(start: Float, stop: Float, fraction: Float): Float =
    (1f - fraction) * start + fraction * stop

