package com.timemeasurer.app.core.domain.stopwatch

import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.common.time.MonotonicClock
import com.timemeasurer.app.core.domain.services.StopwatchServiceActions
import com.timemeasurer.app.core.model.icon.DefaultIconIds
import com.timemeasurer.app.core.model.stopwatch.StopwatchMetadataModel
import com.timemeasurer.app.core.model.stopwatch.StopwatchModel
import com.timemeasurer.app.core.model.stopwatch.StopwatchSettingsModel
import com.timemeasurer.app.core.model.stopwatch.StopwatchTickModel
import com.timemeasurer.app.core.remote_services.AnalyticsService
import com.timemeasurer.app.core.remote_services.CrashlyticsService
import com.timemeasurer.app.core.remote_services.NoOpAnalyticsService
import com.timemeasurer.app.core.remote_services.NoOpCrashlyticsService
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Job
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.catch
import kotlinx.coroutines.flow.combine
import kotlinx.coroutines.flow.distinctUntilChanged
import kotlinx.coroutines.flow.emitAll
import kotlinx.coroutines.flow.flatMapLatest
import kotlinx.coroutines.flow.flow
import kotlinx.coroutines.flow.flowOn
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock

class StopwatchesInteractors(
    private val getStopwatchesUseCase: GetStopwatchesUseCase,
    private val createNewStopwatchUseCase: CreateNewStopwatchUseCase,
    private val updateStopwatchUseCase: UpdateStopwatchUseCase,
    private val deleteStopwatchUseCase: DeleteStopwatchUseCase,
    private val getStopwatchByIdUseCase: GetStopwatchByIdUseCase,
    private val getAllLapsByStopwatchIdUseCase: GetAllLapsByStopwatchIdUseCase,
    private val createNewLapUseCase: CreateNewLapUseCase,
    private val updateLapUseCase: UpdateLapUseCase,
    private val updateAndCreateLapUseCase: UpdateAndCreateLapUseCase,
    private val deleteLapsByStopwatchIdUseCase: DeleteLapsByStopwatchIdUseCase,
    private val ioScope: CoroutineScope,
    private val ioDispatcher: CoroutineDispatcher,
    private val clock: MonotonicClock,
    private val crashlytics: CrashlyticsService = NoOpCrashlyticsService(),
    private val analytics: AnalyticsService = NoOpAnalyticsService(),
) : StopwatchServiceActions {

    private val stopwatchesMutex = Mutex()
    private val stopwatchesInteractors = mutableMapOf<Long, StopwatchInteractor>()
    private var actionJob: Job? = null

    private fun getStopwatchInteractor(stopwatchModel: StopwatchModel): StopwatchInteractor =
        StopwatchInteractor(
            stopwatchModel = stopwatchModel,
            getStopwatchByIdUseCase = getStopwatchByIdUseCase,
            getAllLapsByStopwatchIdUseCase = getAllLapsByStopwatchIdUseCase,
            createNewLapUseCase = createNewLapUseCase,
            updateLapUseCase = updateLapUseCase,
            updateAndCreateLapUseCase = updateAndCreateLapUseCase,
            deleteLapsByStopwatchIdUseCase = deleteLapsByStopwatchIdUseCase,
            ioScope = ioScope,
            ioDispatcher = ioDispatcher,
            clock = clock,
            crashlytics = crashlytics,
        )

    val interactors: StateFlow<Result<List<Pair<Long, StopwatchInteractor>>>> = flow {
        emitAll(getStopwatchesUseCase())
    }.map { result ->
        when (result) {
            is Result.Error -> result
            is Result.Loading -> result
            is Result.Success<List<StopwatchModel>> -> stopwatchesMutex.withLock {
                if (result.data.isEmpty()) {
                    stopwatchesInteractors.clear()
                    when (val stopwatch = createNewStopwatchUseCase(name = "")) {
                        is Result.Error -> return@map stopwatch
                        is Result.Loading -> return@map stopwatch
                        is Result.Success<StopwatchModel> ->
                            stopwatchesInteractors[stopwatch.data.id] = getStopwatchInteractor(stopwatch.data)
                    }
                } else {
                    val ids = stopwatchesInteractors.keys.toMutableSet()
                    result.data.forEach {
                        ids.remove(it.id)
                        if (!stopwatchesInteractors.contains(it.id)) {
                            stopwatchesInteractors[it.id] = getStopwatchInteractor(it)
                        }
                    }
                    ids.forEach { stopwatchesInteractors.remove(it) }
                }
                Result.Success(stopwatchesInteractors.toList())
            }
        }
    }
    .catch {
        crashlytics.log("StopwatchesInteractors() - interactors")
        crashlytics.recordException(it)
        emit(Result.Error(exception = it, error = it.message))
    }
    .flowOn(ioDispatcher)
    .stateIn(ioScope, SharingStarted.Lazily, Result.Success(emptyList()))

    val metadataState: StateFlow<Result<List<StopwatchMetadataModel>>> = interactors
        .flatMapLatest { result ->
            flow<Result<List<StopwatchMetadataModel>>> {
                when (result) {
                    is Result.Error -> emit(result)
                    is Result.Loading -> emit(result)
                    is Result.Success<List<Pair<Long, StopwatchInteractor>>> -> {
                        if (result.data.isEmpty()) {
                            emit(Result.Success(emptyList()))
                            return@flow
                        }
                        combine(result.data.map { it.second.metadataState }) { states ->
                            states.mapNotNull { state ->
                                when (state) {
                                    is Result.Loading -> return@mapNotNull null
                                    is Result.Error -> return@mapNotNull null
                                    is Result.Success<StopwatchMetadataModel> -> state.data
                                }
                            }
                        }.collect {
                            emit(Result.Success(it))
                        }
                    }
                }
            }
        }
        .catch {
            crashlytics.log("StopwatchesInteractors() - metadataState")
            crashlytics.recordException(it)
            println("StopwatchesInteractors() - metadataState - catch: ${it.message}")
            emit(Result.Error(exception = it, error = it.message))
        }
        .flowOn(ioDispatcher)
        .distinctUntilChanged()
        .stateIn(ioScope, SharingStarted.Eagerly, Result.Success(emptyList()))

    val tickState: StateFlow<Map<Long, StateFlow<Result<StopwatchTickModel>>>> = interactors
        .flatMapLatest { result ->
            flow<Map<Long, StateFlow<Result<StopwatchTickModel>>>> {
                when (result) {
                    is Result.Error -> emit(emptyMap())
                    is Result.Loading -> emit(emptyMap())
                    is Result.Success<List<Pair<Long, StopwatchInteractor>>> -> {
                        if (result.data.isEmpty()) {
                            emit(emptyMap())
                            return@flow
                        }
                        emit(result.data.associate { it.first to it.second.tickState })
                    }
                }
            }
        }
        .catch {
            crashlytics.log("StopwatchesInteractors() - tickState")
            crashlytics.recordException(it)
            println("StopwatchesInteractors() - tickState - catch: ${it.message}")
            emit(emptyMap())
        }
        .flowOn(ioDispatcher)
        .stateIn(ioScope, SharingStarted.Lazily, emptyMap())

    override fun startStop(stopwatchId: Long) {
        if (actionJob?.isActive == true) return
        actionJob = ioScope.launch {
            stopwatchesMutex.withLock {
                val interactor = stopwatchesInteractors[stopwatchId] ?: return@withLock
                val wasRunning = interactor.isRunning
                interactor.startStop()
                analytics.logEvent("stopwatch_start_stop", mapOf("stopwatch_id" to stopwatchId, "is_running" to !wasRunning))
            }
        }
    }

    fun reset(stopwatchId: Long) {
        if (actionJob?.isActive == true) return
        actionJob = ioScope.launch {
            stopwatchesMutex.withLock {
                stopwatchesInteractors[stopwatchId]?.reset()
                analytics.logEvent("stopwatch_reset", mapOf("stopwatch_id" to stopwatchId))
            }
        }
    }

    override fun lap(stopwatchId: Long) {
        if (actionJob?.isActive == true) return
        actionJob = ioScope.launch {
            stopwatchesMutex.withLock {
                stopwatchesInteractors[stopwatchId]?.lap()
                analytics.logEvent("stopwatch_lap", mapOf("stopwatch_id" to stopwatchId))
            }
        }
    }

    fun create(name: String, iconId: String = DefaultIconIds.STOPWATCH) {
        if (actionJob?.isActive == true) return
        actionJob = ioScope.launch {
            when (val result = createNewStopwatchUseCase(name = name, settings = StopwatchSettingsModel(iconId = iconId))) {
                is Result.Error -> {}
                is Result.Loading -> {}
                is Result.Success<StopwatchModel> -> {}
            }
        }
    }

    fun rename(stopwatchId: Long, name: String, iconId: String = "") {
        if (actionJob?.isActive == true) return
        actionJob = ioScope.launch {
            when (val result = updateStopwatchUseCase(stopwatchId = stopwatchId, newName = name, iconId = iconId)) {
                is Result.Error -> {}
                is Result.Loading -> {}
                is Result.Success<Long> -> {}
            }
        }
    }

    fun delete(stopwatchId: Long) {
        if (actionJob?.isActive == true) return
        actionJob = ioScope.launch {
            deleteStopwatchUseCase(stopwatchId)
        }
    }

    fun setVisible(stopwatchId: Long, isVisible: Boolean) {
        ioScope.launch {
            stopwatchesMutex.withLock {
                stopwatchesInteractors[stopwatchId]?.setVisible(isVisible)
            }
        }
    }
}
