package com.timemeasurer.app.core.data.repositories.stopwatch_laps

import app.cash.sqldelight.async.coroutines.awaitAsList
import app.cash.sqldelight.async.coroutines.awaitAsOne
import app.cash.sqldelight.async.coroutines.awaitAsOneOrNull
import app.cash.sqldelight.coroutines.asFlow
import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.common.result.startLoading
import com.timemeasurer.app.core.data.database.AppDatabase
import com.timemeasurer.app.core.data.model.entitiesToStopwatchLapsModels
import com.timemeasurer.app.core.data.model.toStopwatchLapModel
import com.timemeasurer.app.core.model.stopwatch.StopwatchLapModel
import com.timemeasurer.app.core.remote_services.CrashlyticsService
import com.timemeasurer.app.core.remote_services.NoOpCrashlyticsService
import data.StopwatchLapsEntity
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.catch
import kotlinx.coroutines.flow.distinctUntilChanged
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.flow.onStart

internal class StopwatchLapsRepositoryImpl(
    private val database: AppDatabase,
    private val scope: CoroutineScope,
    private val crashlytics: CrashlyticsService = NoOpCrashlyticsService()
) : StopwatchLapsRepository {

    override suspend fun getAllLapsByStopwatchId(stopwatchId: Long): Flow<Result<List<StopwatchLapModel>>> {
        val dbFlow = database.db().stopwatch_lapsQueries.selectAllByStopwatchId(stopwatchId)
            .asFlow()
            .map { it.awaitAsList() }
            .map<List<StopwatchLapsEntity>, Result<List<StopwatchLapModel>>> {
                Result.Success(it.entitiesToStopwatchLapsModels())
            }
            .onStart { emit(Result.Loading) }
            .catch {
                crashlytics.log("StopwatchLapsRepositoryImpl() - getAllLapsByStopwatchId()")
                crashlytics.recordException(it)
                println("StopwatchLapsRepositoryImpl() - getAllLapsByStopwatchId() - error: $it")
                emit(Result.Error(it))
            }

        return dbFlow.startLoading()
            .distinctUntilChanged()
    }

    override suspend fun getLastLap(stopwatchId: Long): Flow<Result<StopwatchLapModel?>> {
        val dbFlow = database.db().stopwatch_lapsQueries.selectLastLap(stopwatchId)
            .asFlow()
            .map { it.awaitAsOneOrNull() }
            .map<StopwatchLapsEntity?, Result<StopwatchLapModel?>> {
                Result.Success(it?.toStopwatchLapModel())
            }
            .onStart { emit(Result.Loading) }
            .catch {
                crashlytics.log("StopwatchLapsRepositoryImpl() - getLastLap()")
                crashlytics.recordException(it)
                println("StopwatchLapsRepositoryImpl() - getLastLap(): $it")
                emit(Result.Error(it))
            }

        return dbFlow.startLoading()
            .distinctUntilChanged()
    }

    override suspend fun getMaxLap(stopwatchId: Long): Flow<Result<Long>> {
        val dbFlow = database.db().stopwatch_lapsQueries.maxLap(stopwatchId)
            .asFlow()
            .map { it.awaitAsOne() }
            .map<Long, Result<Long>> { Result.Success(it) }
            .onStart { emit(Result.Loading) }
            .catch {
                crashlytics.log("StopwatchLapsRepositoryImpl() - getMaxLap()")
                crashlytics.recordException(it)
                println("StopwatchLapsRepositoryImpl() - getMaxLap() - error: $it")
                emit(Result.Error(it))
            }

        return dbFlow.startLoading()
            .distinctUntilChanged()
    }

    override suspend fun updateLap(id: Long, time: Long): Result<StopwatchLapModel> {
        val result = runCatching {
            database.db().stopwatch_lapsQueries.updateAndReturn(
                id = id,
                time = time
            ).awaitAsOne()
        }
        result.exceptionOrNull()?.let {
            crashlytics.log("StopwatchLapsRepositoryImpl() - updateLap()")
            crashlytics.recordException(it)
        }

        val lap = result.getOrNull()
        println("StopwatchLapsRepositoryImpl() - updateLap(): ${lap}, ${result.exceptionOrNull()}")
        return if (lap != null) Result.Success(lap.toStopwatchLapModel())
            else Result.Error(exception = result.exceptionOrNull(), error = "Create lap fail")
    }

    override suspend fun createNewLap(stopwatchId: Long, time: Long): Result<StopwatchLapModel> {
        val result = runCatching {
            database.db().stopwatch_lapsQueries.insertNewLapAndReturn(
                stopwatchId = stopwatchId,
                time = time
            ).awaitAsOneOrNull()
        }
        result.exceptionOrNull()?.let {
            crashlytics.log("StopwatchLapsRepositoryImpl() - createNewLap()")
            crashlytics.recordException(it)
        }

        val lap = result.getOrNull()
        println("StopwatchLapsRepositoryImpl() - createNewLap(): ${lap}, ${result.exceptionOrNull()}")
        return if (lap != null) Result.Success(lap.toStopwatchLapModel())
            else Result.Error(exception = result.exceptionOrNull(), error = "Create lap fail")
    }

    override suspend fun updateAndCreateLap(stopwatchId: Long, lapId: Long, time: Long): Result<StopwatchLapModel> {
        val result = runCatching {
            database.db().stopwatch_lapsQueries.updateAndCreate(
                stopwatchId = stopwatchId,
                id = lapId,
                time = time
            ).awaitAsOne()
        }
        result.exceptionOrNull()?.let {
            crashlytics.log("StopwatchLapsRepositoryImpl() - updateAndCreateLap()")
            crashlytics.recordException(it)
        }

        val lap = result.getOrNull()
        println("StopwatchLapsRepositoryImpl() - updateAndCreateLap(): ${lap}, ${result.exceptionOrNull()}")
        return if (lap != null) Result.Success(lap.toStopwatchLapModel())
            else Result.Error(exception = result.exceptionOrNull(), error = "Update and create lap fail")
    }

    override suspend fun createExistLap(item: StopwatchLapModel): Result<StopwatchLapModel> {
        val result = runCatching {
            database.db().stopwatch_lapsQueries.insertAndReturn(
                stopwatchId = item.stopwatchId,
                lap = item.lapNumber.toLong(),
                time = item.time
            ).awaitAsOneOrNull()
        }
        result.exceptionOrNull()?.let {
            crashlytics.log("StopwatchLapsRepositoryImpl() - createExistLap()")
            crashlytics.recordException(it)
        }

        val lap = result.getOrNull()
        println("StopwatchLapsRepositoryImpl() - createExistLap(): ${lap}, ${result.exceptionOrNull()}")
        return if (lap != null) Result.Success(lap.toStopwatchLapModel())
            else Result.Error(exception = result.exceptionOrNull(), error = "Create lap fail")
    }

    override suspend fun deleteLapsByStopwatchId(stopwatchId: Long): Result<Long> {
        val result = runCatching {
            database.db().stopwatch_lapsQueries.deleteLapsByStopwatchId(stopwatchId)
        }
        result.exceptionOrNull()?.let {
            crashlytics.log("StopwatchLapsRepositoryImpl() - deleteLapsByStopwatchId()")
            crashlytics.recordException(it)
        }

        val rowsCount = result.getOrNull() ?: 0L
        println("StopwatchLapsRepositoryImpl() - deleteLapsByStopwatchId(): ${rowsCount}, ${result.exceptionOrNull()}")
        return if (rowsCount >= 0) Result.Success(rowsCount)
            else Result.Error(exception = result.exceptionOrNull(), error = "Rows deleted error")
    }
}
