@Composable
fun StopwatchLapsList(
    laps: List<StopwatchLapModel>,
    modifier: Modifier = Modifier
) {
    if (laps.isEmpty()) return

    val listState = rememberLazyListState()
    var previousSize by remember { mutableIntStateOf(laps.size) }
    val newestLapId = remember { mutableStateOf<Long?>(null) }

    val isAtEnd by remember {
        derivedStateOf {
            val layoutInfo = listState.layoutInfo
            val lastVisibleItem = layoutInfo.visibleItemsInfo.lastOrNull()
            lastVisibleItem != null && lastVisibleItem.index >= laps.lastIndex - 1
        }
    }

    LaunchedEffect(laps.size) {
        if (laps.size > previousSize) {
            newestLapId.value = laps.lastOrNull()?.id
            if (isAtEnd) {
                listState.scrollToItem(laps.lastIndex)
            } else {
                listState.animateScrollToItem(laps.lastIndex)
            }
        } else {
            newestLapId.value = null
        }
        previousSize = laps.size
    }

    LaunchedEffect(newestLapId.value) {
        if (newestLapId.value != null) {
            delay(500)
            newestLapId.value = null
        }
    }

    LazyRow(
        state = listState,
        modifier = modifier
            .fillMaxWidth()
            .wrapContentHeight(),
        contentPadding = PaddingValues(horizontal = 16.dp),
        horizontalArrangement = Arrangement.spacedBy(4.dp, Alignment.CenterHorizontally),
        verticalAlignment = Alignment.CenterVertically
    ) {
        items(laps, key = { it.id }) { lap ->
            val isNewest = lap.id == newestLapId.value
            val scale by animateFloatAsState(
                targetValue = if (isNewest) 1.08f else 1f,
                animationSpec = spring(
                    dampingRatio = Spring.DampingRatioMediumBouncy,
                    stiffness = Spring.StiffnessLow
                ),
                label = "lapScale"
            )

            key(lap.id) {
                LapItem(
                    lapNumber = lap.lapNumber,
                    lapTime = lap.formattedDuration(),
                    cumulativeTime = lap.totalTimeFromStart.millisecondsToFormatStopwatchTime(),
                    labelColor = MaterialTheme.colorScheme.onSurfaceVariant,
                    timeColor = MaterialTheme.colorScheme.onSurface,
                    modifier = Modifier
                        .wrapContentSize()
                        .animateItem()
                        .graphicsLayer {
                            scaleX = scale
                            scaleY = scale
                        }
                )
            }
        }
    }
}

@Composable
internal fun LapItem(
    lapNumber: Int,
    lapTime: String,
    cumulativeTime: String,
    labelColor: Color,
    timeColor: Color,
    modifier: Modifier = Modifier
) {
    Column(
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.Center,
        modifier = modifier
            .border(
                width = 0.5.dp,
                color = MaterialTheme.colorScheme.outline.copy(alpha = 0.3f),
                shape = RoundedCornerShape(4.dp)
            )
            .padding(horizontal = 12.dp, vertical = 8.dp)
    ) {
        Text(
            text = stringResource(Res.string.stopwatches_statistics_lap_label, lapNumber),
            style = MaterialTheme.typography.titleSmall,
            color = labelColor
        )
        Text(
            text = lapTime,
            style = MaterialTheme.typography.titleLarge,
            color = timeColor,
            fontWeight = FontWeight.SemiBold,
        )
        Text(
            text = cumulativeTime,
            style = MaterialTheme.typography.titleSmall,
            color = timeColor,
            fontWeight = FontWeight.SemiBold,
        )
    }
}

internal fun StopwatchLapModel.formattedDuration(): String =
    durationMs().millisecondsToFormatStopwatchTime()

