package com.timemeasurer.app.core.ui.components

import androidx.compose.foundation.background
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.size
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.tooling.preview.Preview
import androidx.compose.ui.unit.dp
import com.timemeasurer.app.core.ui.theme.AppTheme
import com.timemeasurer.app.core.ui.theme.LocalBackgroundTheme

@Composable
fun AppBackground(
    modifier: Modifier = Modifier,
    content: @Composable () -> Unit,
) {
    val backgroundTheme = LocalBackgroundTheme.current
    val brush = backgroundTheme.gradientBrush
    Box(
        modifier = modifier
            .fillMaxSize()
            .then(
                if (brush != null) {
                    Modifier.background(brush = brush)
                } else {
                    val color = backgroundTheme.color
                    Modifier.background(if (color == Color.Unspecified) Color.Transparent else color)
                }
            ),
    ) {
        content()
    }
}


@Preview
@Composable
fun BackgroundDefault() {
    AppTheme {
        AppBackground(Modifier.size(100.dp), content = {})
    }
}

@Preview
@Composable
fun BackgroundDynamic() {
    AppTheme {
        AppBackground(Modifier.size(100.dp), content = {})
    }
}

